export const RecordManualAdSpendOutputSchema = z.object({
	adSpendId: z.uuid(),
})

/**
 * C33 RecordManualAdSpend. Materialises a MANUAL AdSpendManual (no provider
 * connection, no Go-worker sync — merchant-entered expense for ROAS
 * attribution). The entity's `create()` validates the date range.
 */
@injectable()
export class RecordManualAdSpend extends Handler<typeof RecordManualAdSpendInputSchema, typeof RecordManualAdSpendOutputSchema> {
	readonly name = 'record_manual_ad_spend' as const
	readonly inputSchema = RecordManualAdSpendInputSchema
	readonly outputSchema = RecordManualAdSpendOutputSchema

	constructor(private readonly adSpends: AdSpendManualRepository) {
		super()
	}

	protected async handle(input: this['input'], tx?: Transaction): Promise<this['output']> {
		return this.withTransaction(tx, async tx => {
			const startDate = new Date(input.startDate)
			startDate.setUTCHours(0, 0, 0, 0)
			const endDate = new Date(input.endDate)
			endDate.setUTCHours(23, 59, 59, 999)

			const entity = AdSpendManual.create({
				storeId: input.storeId,
				// MANUAL rows have no platform.
				currency: input.currency,
				startDate,
				endDate,
				spend: { amountCents: input.amountCents, currency: input.currency },
				name: input.name,
				description: input.description,
				createdByUserId: input.userId,
			})

			await this.adSpends.save(entity, tx)

			await this.domainEventRepository.save(
				new ManualAdSpendRecordedEvent({
					entityId: entity.id.value,
					ownerId: entity.storeId.value,
					// toJSON() serialises Id instances to strings; z.instance(Id) accepts
					// both at runtime — the cast bridges the TS mismatch.
					payload: { adSpend: entity.toJSON() as unknown as Z.infer<typeof AdSpendManualSchema> },
				}),
				tx,
			)

			return { adSpendId: entity.id.value }
		})
	}
}

import { injectable } from 'tsyringe-neo'
import { and, count, desc, eq, gte, inArray, lte, sql } from 'drizzle-orm'
import { DrizzleClient, tryCatchAsync } from '@bk-dash/core-typescript'
import { adSpends } from '@bk-dash/contracts/db'
import { AdSpendManual, AdSpendManualSchema } from '../../entities/AdSpendManual'
import { AdSpendManualRepository, type AdSpendBreakdownQuery, type AdSpendBreakdownResult } from './AdSpendManualRepository'

/**
 * Drizzle-backed AdSpendManualRepository. Reads/writes MANUAL rows in the
 * shared `ad_spends` table. The Go sync worker writes AUTOMATIC rows to the
 * same table (sqlc-owned); TS only touches entity-shaped columns for MANUAL.
 *
 * `breakdown` filters by storeId + optional storeIntegrationIds +
 * date-range overlap on (startDate, endDate), paginates newest-first
 * by startDate. Returns the entity for caller-side mapping.
 */
@injectable()
export class DrizzleAdSpendManualRepository extends AdSpendManualRepository {
	constructor(private db: DrizzleClient) {
		super()
	}

	async findById(id: string, tx?: DrizzleClient): Promise<AdSpendManual | undefined> {
		const dbc = tx ?? this.db
		const result = await tryCatchAsync(async () => {
			const rows = await dbc.select().from(adSpends).where(eq(adSpends.id, id)).limit(1)
			return rows[0]
		})
		if (!result.success || !result.data) return undefined
		return this.toDomain(result.data)
	}

	async breakdown(query: AdSpendBreakdownQuery, tx?: DrizzleClient): Promise<AdSpendBreakdownResult> {
		const dbc = tx ?? this.db
		const filters = [
			eq(adSpends.storeId, query.storeId),
			// Date-range overlap: row.endDate >= query.from AND row.startDate <= query.to.
			gte(adSpends.endDate, query.from.toISOString()),
			lte(adSpends.startDate, query.to.toISOString()),
		] as any[]
		if (query.storeIntegrationIds !== undefined && query.storeIntegrationIds.length > 0) {
			// Match on storeIntegrationExternalId since the entity exposes that name.
			filters.push(inArray(adSpends.storeIntegrationExternalId, query.storeIntegrationIds))
		}
		const where = and(...filters)
		const result = await tryCatchAsync(async () => {
			const offset = Math.max(0, (query.page - 1) * query.limit)
			const [items, totalRows] = await Promise.all([
				dbc
					.select()
					.from(adSpends)
					.where(where ?? sql`true`)
					.orderBy(desc(adSpends.startDate))
					.limit(query.limit)
					.offset(offset),
				dbc
					.select({ value: count() })
					.from(adSpends)
					.where(where ?? sql`true`),
			])
			return { items, total: Number(totalRows[0]?.value ?? 0) }
		})
		if (!result.success) throw result.error
		return {
			total: result.data.total,
			items: result.data.items.map(r => this.toDomain(r)),
		}
	}

	async save(entity: AdSpendManual, tx?: DrizzleClient): Promise<AdSpendManual> {
		entity.incrementVersion()
		const dbc = tx ?? this.db
		const result = await tryCatchAsync(async () => {
			const data = this.toPersistence(entity)
			await dbc
				.insert(adSpends)
				.values(data)
				.onConflictDoUpdate({
					target: adSpends.id,
					set: {
						storeId: data.storeId,
						storeIntegrationExternalId: data.storeIntegrationExternalId,
						platform: data.platform,
						amountCents: data.amountCents,
						currency: data.currency,
						startDate: data.startDate,
						endDate: data.endDate,
						groupBy: data.groupBy,
						impressions: data.impressions,
						clicks: data.clicks,
						conversions: data.conversions,
						campaignExternalId: data.campaignExternalId,
						adAccountExternalId: data.adAccountExternalId,
						name: data.name,
						description: data.description,
						bindings: data.bindings,
						createdByUserId: data.createdByUserId,
						disabledAt: data.disabledAt,
						updatedAt: new Date(),
						version: data.version,
					},
				})
			return entity
		})
		if (!result.success) throw result.error
		return result.data
	}

	async delete(id: string, tx?: DrizzleClient): Promise<void> {
		const dbc = tx ?? this.db
		const result = await tryCatchAsync(async () => {
			await dbc.delete(adSpends).where(eq(adSpends.id, id))
		})
		if (!result.success) throw result.error
	}

	private toDomain(row: typeof adSpends.$inferSelect): AdSpendManual {
		// Coerce legacy date-only strings ('2026-05-01') to ISO datetimes.
		// TODO: remove after legacy date-only rows are migrated.
		const startDate = new Date(row.startDate.includes('T') ? row.startDate : `${row.startDate}T00:00:00.000Z`)
		const endDate = new Date(row.endDate.includes('T') ? row.endDate : `${row.endDate}T23:59:59.999Z`)
		const parsed = AdSpendManualSchema.parse({
			storeId: row.storeId,
			adAccountExternalId: row.adAccountExternalId ?? undefined,
			campaignExternalId: row.campaignExternalId ?? undefined,
			// Stored 'MANUAL' or null in platform column — both map to undefined.
			platform: row.platform === 'MANUAL' || row.platform === null ? undefined : row.platform,
			currency: row.currency,
			startDate,
			endDate,
			groupBy: row.groupBy,
			spend: { amountCents: Number(row.amountCents), currency: row.currency },
			impressions: row.impressions ?? undefined,
			clicks: row.clicks ?? undefined,
			conversions: row.conversions ?? undefined,
			name: row.name ?? undefined,
			description: row.description ?? undefined,
			bindings: row.bindings ?? undefined,
			createdByUserId: row.createdByUserId ?? '',
			disabledAt: row.disabledAt ?? undefined,
		})
		return new AdSpendManual({
			...parsed,
			id: row.id,
			createdAt: row.createdAt,
			updatedAt: row.updatedAt,
			version: row.version,
		})
	}

	private toPersistence(entity: AdSpendManual): typeof adSpends.$inferInsert {
		return {
			id: entity.id.value,
			storeId: entity.storeId.value,
			storeIntegrationExternalId: entity.adAccountExternalId ?? null,
			platform: entity.platform ?? null,
			amountCents: BigInt(entity.spend.amountCents),
			currency: entity.spend.currency,
			startDate: entity.startDate.toISOString(),
			endDate: entity.endDate.toISOString(),
			groupBy: entity.groupBy,
			impressions: entity.impressions ?? null,
			clicks: entity.clicks ?? null,
			conversions: entity.conversions ?? null,
			campaignExternalId: entity.campaignExternalId ?? null,
			adAccountExternalId: entity.adAccountExternalId ?? null,
			name: entity.name ?? null,
			description: entity.description ?? null,
			bindings: entity.bindings ?? null,
			createdByUserId: entity.createdByUserId.value,
			disabledAt: entity.disabledAt ?? null,
			version: entity.version,
		}
	}
}

