// Sales given-helpers — repo-direct. Always composes givenStoreWithOwner + givenStoreIntegration
// to satisfy FK constraints (OrderOverride references store + integration external id).
import type { TestBed } from '../TestBed'
import { OrderOverride } from '@sales/entities/OrderOverride'
import { OrderOverrideRepository } from '@sales/repositories/OrderOverrideRepository'
import { givenStoreWithOwner } from './stores'
import { givenStoreIntegration } from './integrations'
import { testId } from '../ids'

export async function givenOrderOverride(
	testBed: TestBed,
	overrides: Partial<{
		storeId: string
		orderId: string
		storeIntegrationExternalId: string
		updatedByUserId: string
		fields: Parameters<typeof OrderOverride.create>[0]['fields']
	}> = {},
): Promise<OrderOverride> {
	const { store, user } = await givenStoreWithOwner(testBed)
	const storeId = overrides.storeId ?? store.id.value
	const userId = overrides.updatedByUserId ?? user.id.value

	const integration = await givenStoreIntegration(testBed, { storeId, ownerId: userId })
	const storeIntegrationExternalId = overrides.storeIntegrationExternalId ?? integration.externalId

	const override = OrderOverride.create({
		storeId,
		orderId: overrides.orderId ?? testId('order', '1'),
		storeIntegrationExternalId,
		fields: overrides.fields ?? {},
		updatedByUserId: userId,
	})

	return testBed.resolve(OrderOverrideRepository).save(override)
}

