import { AggregateRoot, BaseError, Id, z } from '@bk-dash/core-typescript'
import Z from 'zod'
import { MarketingPlatform, AdSpendGroupBy, CurrencyCode } from '@bk-dash/contracts-typescript/wire/enums'
import { MonetaryAmount } from '../../shared/objects'
import type { MarketingDomainErrors } from '../errors'

export const ManualMarketingExpenseBindingSchema = z.object({
	productId: z.string().optional(),
	variantId: z.string().optional(),
})

export const AdSpendManualSchema = z
	.object({
		storeId: z.instance(Id),
		adAccountExternalId: z.string().optional(),
		campaignExternalId: z.string().optional(),
		// Optional: MANUAL rows store null in DB; undefined here means no platform.
		platform: z.enum(MarketingPlatform).optional(),
		currency: z.enum(CurrencyCode),
		// Full ISO 8601 datetime strings required. Legacy date-only DB rows
		// ('2026-05-01') are normalised to datetime in toDomain before parse.
		// TODO: remove toDomain coercion after legacy date-only rows migrate.
		startDate: z.date(),
		endDate: z.date(),
		groupBy: z.enum(AdSpendGroupBy),
		spend: z.instance(MonetaryAmount),
		impressions: z.number().int().optional(),
		clicks: z.number().int().optional(),
		conversions: z.number().int().optional(),
		name: z.string().optional(),
		description: z.string().optional(),
		bindings: z.array(ManualMarketingExpenseBindingSchema).optional(),
		createdByUserId: z.instance(Id),
		disabledAt: z.date().optional(),
	})
	.refine(data => data.startDate <= data.endDate, {
		error: 'INVALID_DATE_RANGE' as MarketingDomainErrors,
	})

export type AdSpendManualProps = Z.infer<typeof AdSpendManualSchema>

export class AdSpendManual extends AggregateRoot<typeof AdSpendManualSchema> {
	static override schema = AdSpendManualSchema

	static create(data: {
		storeId: string
		adAccountExternalId?: string
		campaignExternalId?: string
		platform?: MarketingPlatform
		currency: CurrencyCode
		startDate: Date
		endDate: Date
		spend: { amountCents: number; currency: CurrencyCode }
		impressions?: number
		clicks?: number
		conversions?: number
		name?: string
		description?: string
		bindings?: Array<{ productId?: string; variantId?: string }>
		createdByUserId: string
	}): AdSpendManual {
		// Named domain-error guard — schema .refine() fires at the schema
		// boundary (safeParse returns false) but BaseEntity maps schema
		// failures to INVALID_ENTITY. We throw the specific code here so
		// callers and tests can assert on INVALID_DATE_RANGE.
		if (data.startDate > data.endDate) {
			throw new BaseError<MarketingDomainErrors>('INVALID_DATE_RANGE', 'startDate must be before or equal to endDate')
		}
		return new AdSpendManual({
			storeId: data.storeId,
			adAccountExternalId: data.adAccountExternalId,
			campaignExternalId: data.campaignExternalId,
			platform: data.platform,
			currency: data.currency,
			startDate: data.startDate,
			endDate: data.endDate,
			groupBy: AdSpendGroupBy.DAILY,
			spend: data.spend,
			impressions: data.impressions,
			clicks: data.clicks,
			conversions: data.conversions,
			name: data.name,
			description: data.description,
			bindings: data.bindings,
			createdByUserId: data.createdByUserId,
		})
	}

	updateManual(patch: {
		name?: string
		description?: string
		startDate?: Date
		endDate?: Date
		spend?: { amountCents: number; currency: CurrencyCode }
		bindings?: Array<{ productId?: string; variantId?: string }>
	}): void {
		// Named domain-error guard — mirrors create() for the same reason.
		const effectiveStart = patch.startDate ?? this.startDate
		const effectiveEnd = patch.endDate ?? this.endDate
		if (effectiveStart > effectiveEnd) {
			throw new BaseError<MarketingDomainErrors>('INVALID_DATE_RANGE', 'startDate must be before or equal to endDate')
		}
		if (patch.name !== undefined) this.name = patch.name
		if (patch.description !== undefined) this.description = patch.description
		if (patch.startDate !== undefined) this.startDate = patch.startDate
		if (patch.endDate !== undefined) this.endDate = patch.endDate
		if (patch.spend !== undefined) this.spend = new MonetaryAmount(patch.spend)
		if (patch.bindings !== undefined) this.bindings = patch.bindings
	}
}

export interface AdSpendManual extends AdSpendManualProps {}

