import { RequireStoreRole } from '../middlewares/RequireStoreRole'
import { UpdateStoreSettings } from '../usecases/UpdateStoreSettings'

export const UpdateStoreSettingsControllerInputSchema = z
	.object({
		ctx: z.object({
			user: z.object({ id: z.string() }),
		}),
		params: z.object({
			storeId: z.uuid(),
		}),
		name: z.string().trim().min(1).max(120).optional(),
		pictureUrl: z.url().nullable().optional(),
		email: z.email().nullable().optional(),
		phoneNumber: z.string().min(5).max(40).nullable().optional(),
	})
	.example([
		{
			ctx: { user: { id: 'user-123' } },
			params: { storeId: '019e4d24-6524-7041-9e1c-8108180cddae' },
			name: 'New Acme',
			pictureUrl: 'https://cdn.example.com/new-logo.png',
		},
	])

export const UpdateStoreSettingsControllerOutputSchema = z.void()

@injectable()
export class UpdateStoreSettingsController extends Controller<
	typeof UpdateStoreSettingsControllerInputSchema,
	typeof UpdateStoreSettingsControllerOutputSchema
> {
	readonly path = '/stores/:storeId/settings'
	readonly method = 'patch' as const
	readonly description = 'Update store profile settings (C13 UpdateStoreSettings)'
	readonly inputSchema = UpdateStoreSettingsControllerInputSchema
	readonly outputSchema = UpdateStoreSettingsControllerOutputSchema

	override middlewares = [AuthAccountMiddleware, RequireStoreMember, RequireStoreRole([Role.OWNER, Role.ADMIN])]

	constructor(private updateStoreSettings: UpdateStoreSettings) {
		super()
	}

	async handle(request: this['input']): Promise<this['output']> {
		await this.updateStoreSettings.execute({
			storeId: request.params.storeId,
			updatedByUserId: request.ctx.user.id,
			name: request.name,
			pictureUrl: request.pictureUrl,
			email: request.email,
			phoneNumber: request.phoneNumber,
		})
		return { status: HttpStatusCode.NO_CONTENT, data: undefined }
	}
}

