import { injectable } from 'tsyringe-neo'
import { BaseError, Handler, z } from '@bk-dash/core-typescript'
import type { Transaction } from '@bk-dash/core-typescript'
import { PlanFeature, Role as TenancyRole } from '@bk-dash/contracts-typescript/wire/enums'
import { StoreRepository } from '../repositories/StoreRepository'
import { StoreMembershipRepository } from '../repositories/StoreMembershipRepository'
import { SubscriptionQueryService } from '../services/SubscriptionQueryService'
import { PlanQuotaService } from '../services/PlanQuotaService'
import { StoreSubscriptionChangedEvent } from '../events'
import type { ApplicationErrors } from '../errors'

export const ChangeStoreSubscriptionInputSchema = z.object({
	storeId: z.uuid(),
	targetSubscriptionId: z.uuid(),
	userId: z.uuid(),
})

export const ChangeStoreSubscriptionOutputSchema = z.object({ storeId: z.uuid() })

/**
 * Reassigns a store whose subscription has ended onto another active
 * subscription the user owns. Guard (old-backend parity): only when the
 * store's CURRENT subscription is inactive. Validates the target is active,
 * owned by the user, and has a free slot.
 */
@injectable()
export class ChangeStoreSubscription extends Handler<
	typeof ChangeStoreSubscriptionInputSchema,
	typeof ChangeStoreSubscriptionOutputSchema
> {
	readonly name = 'change_store_subscription' as const
	readonly inputSchema = ChangeStoreSubscriptionInputSchema
	readonly outputSchema = ChangeStoreSubscriptionOutputSchema

	constructor(
		private readonly storeRepo: StoreRepository,
		private readonly membershipRepo: StoreMembershipRepository,
		private readonly subscriptionQuery: SubscriptionQueryService,
		private readonly planQuota: PlanQuotaService,
	) {
		super()
	}

	protected async handle(input: this['input'], tx?: Transaction): Promise<this['output']> {
		const store = await this.storeRepo.findById(input.storeId)
		if (!store) throw new BaseError<ApplicationErrors>('STORE_NOT_FOUND')

		const membership = await this.membershipRepo.findByStoreAndUser(input.storeId, input.userId)
		if (!membership || membership.role !== TenancyRole.OWNER) {
			throw new BaseError<ApplicationErrors>('STORE_MEMBERSHIP_NOT_FOUND')
		}

		// Guard: only reassign when the current subscription is inactive.
		const fromSubscriptionId = store.subscriptionId
		if (fromSubscriptionId) {
			const current = await this.subscriptionQuery.getSubscriptionById(fromSubscriptionId)
			if (current?.isActive) throw new BaseError<ApplicationErrors>('STORE_SUBSCRIPTION_STILL_ACTIVE')
		}

		// Validate the target: exists → owned → active → has a free slot.
		const target = await this.subscriptionQuery.getSubscriptionById(input.targetSubscriptionId)
		if (!target || !target.isActive) throw new BaseError<ApplicationErrors>('SUBSCRIPTION_NOT_FOUND')
		if (target.userId !== input.userId) throw new BaseError<ApplicationErrors>('SUBSCRIPTION_NOT_OWNED')

		const counts = await this.storeRepo.countStoresBySubscriptionIds([input.targetSubscriptionId])
		if ((counts[input.targetSubscriptionId] ?? 0) >= this.planQuota.quotaFor(target.tier, PlanFeature.STORE_AMOUNT)) {
			throw new BaseError<ApplicationErrors>('TARGET_SUBSCRIPTION_FULL')
		}

		return this.withTransaction(tx, async tx => {
			store.changeSubscription(input.targetSubscriptionId)
			await this.storeRepo.save(store, tx)
			await this.domainEventRepository.save(
				new StoreSubscriptionChangedEvent({
					entityId: store.id.value,
					ownerId: input.userId,
					payload: {
						storeId: store.id.value,
						fromSubscriptionId,
						toSubscriptionId: input.targetSubscriptionId,
						changedByUserId: input.userId,
					},
				}),
				tx,
			)
			return { storeId: store.id.value }
		})
	}
}

import { injectable } from 'tsyringe-neo'
import { Handler, z } from '@bk-dash/core-typescript'
import type { Transaction } from '@bk-dash/core-typescript'
import { CurrencyCode } from '@bk-dash/contracts-typescript/wire/enums'
import { AdSpendManual, AdSpendManualSchema } from '../entities/AdSpendManual'
import Z from 'zod'
import { AdSpendManualRepository } from '../repositories/AdSpendManualRepository'
import { ManualAdSpendRecordedEvent } from '../events'

export const RecordManualAdSpendInputSchema = z.object({
	userId: z.uuid(),
	storeId: z.uuid(),
	startDate: z.date(),
	endDate: z.date(),
	currency: z.enum(CurrencyCode),
	amountCents: z.number().int().positive(),
	description: z.string().optional(),
	name: z.string().optional(),
})

export const RecordManualAdSpendOutputSchema = z.object({
	adSpendId: z.uuid(),
})

/**
 * C33 RecordManualAdSpend. Materialises a MANUAL AdSpendManual (no provider
 * connection, no Go-worker sync — merchant-entered expense for ROAS
 * attribution). The entity's `create()` validates the date range.
 */
@injectable()
export class RecordManualAdSpend extends Handler<typeof RecordManualAdSpendInputSchema, typeof RecordManualAdSpendOutputSchema> {
	readonly name = 'record_manual_ad_spend' as const
	readonly inputSchema = RecordManualAdSpendInputSchema
	readonly outputSchema = RecordManualAdSpendOutputSchema

	constructor(private readonly adSpends: AdSpendManualRepository) {
		super()
	}

	protected async handle(input: this['input'], tx?: Transaction): Promise<this['output']> {
		return this.withTransaction(tx, async tx => {
			const startDate = new Date(input.startDate)
			startDate.setUTCHours(0, 0, 0, 0)
			const endDate = new Date(input.endDate)
			endDate.setUTCHours(23, 59, 59, 999)

			const entity = AdSpendManual.create({
				storeId: input.storeId,
				// MANUAL rows have no platform.
				currency: input.currency,
				startDate,
				endDate,
				spend: { amountCents: input.amountCents, currency: input.currency },
				name: input.name,
				description: input.description,
				createdByUserId: input.userId,
			})

			await this.adSpends.save(entity, tx)

			await this.domainEventRepository.save(
				new ManualAdSpendRecordedEvent({
					entityId: entity.id.value,
					ownerId: entity.storeId.value,
					// toJSON() serialises Id instances to strings; z.instance(Id) accepts
					// both at runtime — the cast bridges the TS mismatch.
					payload: { adSpend: entity.toJSON() as unknown as Z.infer<typeof AdSpendManualSchema> },
				}),
				tx,
			)

			return { adSpendId: entity.id.value }
		})
	}
}

import { injectable } from 'tsyringe-neo'
import { BaseError, Handler, z } from '@bk-dash/core-typescript'
import type { Transaction } from '@bk-dash/core-typescript'
import { NotificationChannel, NotificationOrigin, NotificationCategory } from '@bk-dash/contracts-typescript/wire/enums'
import { BkdashNotification } from '../entities/BkdashNotification'
import { BkdashNotificationDelivery } from '../entities/BkdashNotificationDelivery'
import { BkdashNotificationRepository } from '../repositories/BkdashNotificationRepository'
import { BkdashNotificationDeliveryRepository } from '../repositories/BkdashNotificationDeliveryRepository'
import { NotificationSentEvent } from '../events'
import type { NotificationsDomainErrors } from '../errors'

export const SendNotificationInputSchema = z.object({
	userId: z.uuid(),
	storeId: z.uuid().optional(),
	targetUserIds: z.array(z.string()).optional(),
	title: z.string().min(1).max(200),
	content: z.string().min(1),
	category: z.enum(NotificationCategory),
	important: z.boolean().default(false),
	pushEnabled: z.boolean().default(true),
	emailEnabled: z.boolean().default(false),
	contentType: z.string().default('text/plain'),
	payload: z.record(z.string(), z.unknown()).optional(),
	scheduledAt: z.date().optional(),
})

export const SendNotificationOutputSchema = z.object({
	notificationId: z.uuid(),
	deliveriesCreated: z.number().int().min(0),
	deliveriesSkippedDuplicate: z.number().int().min(0),
})

/**
 * C53 SendNotification. Creates one BkdashNotification + N
 * BkdashNotificationDelivery rows (one per recipient × enabled channel).
 * Requires at least one targetUserId and at least one enabled channel.
 *
 * `scheduledAt` is accepted for SDK compatibility but not yet honored at
 * this layer — the scheduler integration that defers the persist to the
 * requested wall-clock lands in a follow-up iter; for now the rows are
 * created immediately with `deliveredAt = now`.
 */
@injectable()
export class SendNotification extends Handler<typeof SendNotificationInputSchema, typeof SendNotificationOutputSchema> {
	readonly name = 'send_notification' as const
	readonly inputSchema = SendNotificationInputSchema
	readonly outputSchema = SendNotificationOutputSchema

	constructor(
		private readonly notifications: BkdashNotificationRepository,
		private readonly deliveries: BkdashNotificationDeliveryRepository,
	) {
		super()
	}

	protected async handle(input: this['input'], tx?: Transaction): Promise<this['output']> {
		const targets = input.targetUserIds ?? []
		if (targets.length === 0) {
			throw new BaseError<NotificationsDomainErrors>('EMPTY_RECIPIENTS')
		}
		const channels: NotificationChannel[] = []
		if (input.pushEnabled) channels.push(NotificationChannel.PUSH)
		if (input.emailEnabled) channels.push(NotificationChannel.EMAIL)
		if (channels.length === 0) {
			throw new BaseError<NotificationsDomainErrors>('NO_CHANNEL_ENABLED')
		}

		return this.withTransaction(tx, async tx => {
			const notification = BkdashNotification.create({
				title: input.title,
				content: input.content,
				category: input.category as NotificationCategory,
				origin: NotificationOrigin.ADMIN,
				important: input.important,
				contentType: input.contentType,
				payload: input.payload,
				storeId: input.storeId ?? null,
				createdByUserId: input.userId,
			})
			await this.notifications.save(notification, tx)

			let deliveriesCreated = 0
			for (const recipient of targets) {
				for (const channel of channels) {
					const delivery = BkdashNotificationDelivery.create({
						notificationId: notification.id.value,
						userId: recipient,
						channel,
					})
					await this.deliveries.save(delivery, tx)
					deliveriesCreated++
				}
			}

			await this.domainEventRepository.save(
				new NotificationSentEvent({
					entityId: notification.id.value,
					ownerId: input.storeId ?? input.userId,
					payload: {
						notificationId: notification.id.value,
						storeId: input.storeId ?? null,
						category: input.category,
						channels,
						recipientCount: targets.length,
						deliveriesCreated,
					},
				}),
				tx,
			)

			return {
				notificationId: notification.id.value,
				deliveriesCreated,
				deliveriesSkippedDuplicate: 0,
			}
		})
	}
}

