import { pgSchema, uuid, text, timestamp, integer, bigint, jsonb, boolean, index, uniqueIndex } from 'drizzle-orm/pg-core'

/**
 * `marketing` is BK Dash's BC6 Marketing schema.
 *
 * Ownership:
 *   - `ad_spends` is **MANUAL-only** (TS-written) — merchants enter
 *     ManualMarketingExpense rows for ROAS attribution. AUTOMATIC rows
 *     now live in the `sync` schema (Go-owned).
 *   - `campaign_product_bindings` is **TS-owned** — merchants link
 *     campaign external IDs to specific products / variants so ROAS
 *     attribution resolves correctly.
 *   - `store_integration_marketing_access` is **TS-owned** — polymorphic
 *     link between StoreIntegration and marketing assets (BusinessAccounts
 *     and AdAccounts) discovered by the Go worker.
 *
 * NOTE: campaigns / ad_sets / ads tables were decommissioned (Spec β.2 D3).
 * Those Go-owned projections now live exclusively in the `sync` schema.
 */
export const marketingSchema = pgSchema('marketing')

/**
 * `ad_spends` MANUAL-only spend rows. AUTOMATIC rows (Go-written pipeline
 * spend) now live in `sync.ad_spends` (Spec β.2 D3 decommission).
 *
 * AUTOMATIC rows: ad_id + bucket_start + group_by (HOURLY/DAILY) +
 * impressions + clicks populated. (storeId+adAccountExternalId+
 * adExternalId+bucketStart+groupBy) is unique — first-insert detection
 * uses the same xmax pattern via the unique index.
 *
 * MANUAL rows: ad_id NULL; manual_binding populated (jsonb mirroring
 * spec's ManualMarketingExpenseBinding — productId? + variantId?);
 * occurred_at filled instead of bucket_start; impressions/clicks NULL.
 */
export const adSpends = marketingSchema.table(
	'ad_spends',
	{
		id: uuid('id').primaryKey().defaultRandom(),

		storeId: uuid('store_id').notNull(),
		storeIntegrationId: uuid('store_integration_id'),
		storeIntegrationExternalId: text('store_integration_external_id'),

		// AUTOMATIC AdSpend now lives Go-side in sync.AdSpend; this table is
		// MANUAL-only (Spec β.2 D2: AdSpend → AdSpendManual rename dropped the
		// AdSpendType discriminator).

		// Shared fields.
		platform: text('platform'),
		amountCents: bigint('amount_cents', { mode: 'bigint' }).notNull(),
		currency: text('currency').notNull(),

		// Time range. Entity-side `startDate` + `endDate` (TS uses ISO
		// date strings — see AdSpend entity). For AUTOMATIC rows, set
		// startDate=endDate=bucketStart. For MANUAL, the merchant
		// supplies a range.
		startDate: text('start_date').notNull(),
		endDate: text('end_date').notNull(),
		// AdSpendGroupBy: HOURLY | DAILY. Default DAILY for MANUAL rows.
		groupBy: text('group_by').notNull().default('DAILY'),

		// Performance counters (provider-reported for AUTOMATIC; merchant-
		// reported optionally for MANUAL).
		impressions: integer('impressions'),
		clicks: integer('clicks'),
		conversions: integer('conversions'),

		// AUTOMATIC-only: provider ad/campaign identifiers.
		adId: uuid('ad_id'),
		campaignId: uuid('campaign_id'),
		adAccountExternalId: text('ad_account_external_id'),
		adExternalId: text('ad_external_id'),
		// Provider-side campaign external id (used by the entity's
		// breakdown; distinct from the FK-resolved campaignId).
		campaignExternalId: text('campaign_external_id'),
		// AUTOMATIC bucket pointer (legacy column kept so Go pipelines
		// retain their write target; entity round-trips via startDate).
		bucketStart: timestamp('bucket_start', { withTimezone: true }),

		// MANUAL: merchant-supplied metadata.
		name: text('name'),
		description: text('description'),
		// jsonb array mirroring spec ManualMarketingExpenseBinding[]:
		// each entry { productId?: string; variantId?: string }.
		bindings: jsonb('bindings'),
		// Legacy singular column (Go writes the AUTOMATIC equivalent).
		manualBinding: jsonb('manual_binding'),
		occurredAt: timestamp('occurred_at', { withTimezone: true }),

		// Spec: who recorded a MANUAL row (audit trail).
		createdByUserId: text('created_by_user_id'),
		// Soft-disable stamp (merchant toggles a MANUAL row off without
		// deleting). UpdateManualAdSpend respects this.
		disabledAt: timestamp('disabled_at', { withTimezone: true }),

		createdAt: timestamp('created_at', { withTimezone: true }).notNull().defaultNow(),
		updatedAt: timestamp('updated_at', { withTimezone: true }).notNull().defaultNow(),
		version: integer('version').notNull().default(1),
	},
	t => ({
		// AUTOMATIC uniqueness: one row per (ad, bucket, granularity).
		// NULLs deduplicate naturally — MANUAL rows always have NULL on
		// adExternalId so they don't collide with AUTOMATIC rows.
		automaticBucketUnq: uniqueIndex('ad_spends_automatic_bucket_unq').on(
			t.storeId,
			t.adAccountExternalId,
			t.adExternalId,
			t.bucketStart,
			t.groupBy,
		),
		storeIdx: index('ad_spends_store_id_idx').on(t.storeId),
		adIdx: index('ad_spends_ad_id_idx').on(t.adId),
		campaignIdx: index('ad_spends_campaign_id_idx').on(t.campaignId),
		// Time-bucketed reads — analytics rolls up by day/week/month.
		bucketStartIdx: index('ad_spends_bucket_start_idx').on(t.bucketStart),
		occurredAtIdx: index('ad_spends_occurred_at_idx').on(t.occurredAt),
	}),
)

/**
 * `store_integration_marketing_access` — polymorphic link between a
 * StoreIntegration and the marketing assets it exposes (BusinessAccounts
 * and AdAccounts). TS-owned; written by external handlers that consume
 * Go-published `marketing_business_account.discovered` /
 * `marketing_ad_account.discovered` integration events.
 *
 * Ownership:
 *   accessType=BUSINESS_ACCOUNT: one row per BM discovered via a StoreIntegration.
 *   accessType=AD_ACCOUNT: one row per ad account under a BM, with parentExternalId
 *     denormalising the BM externalId for group-by-BM queries.
 *
 * Unique constraint: (storeIntegrationId, accessType, platform, externalId) —
 * enables idempotent UPSERT on re-discovery without gaps or duplicate rows.
 */
export const storeIntegrationMarketingAccess = marketingSchema.table(
	'store_integration_marketing_access',
	{
		id: uuid('id').primaryKey(),

		storeIntegrationId: uuid('store_integration_id').notNull(),

		// 'BUSINESS_ACCOUNT' | 'AD_ACCOUNT'
		accessType: text('access_type').notNull(),

		// MarketingPlatform: META | GOOGLE_ADS | TIKTOK | TABOOLA
		platform: text('platform').notNull(),

		externalId: text('external_id').notNull(),
		name: text('name').notNull(),

		// Denorm: BM externalId for AD_ACCOUNT rows; null for BUSINESS_ACCOUNT.
		parentExternalId: text('parent_external_id'),

		// Denorm: ad-account currency for AD_ACCOUNT rows; null for BUSINESS_ACCOUNT.
		currency: text('currency'),

		active: boolean('active').notNull().default(false),

		validFrom: timestamp('valid_from', { mode: 'date' }),
		validTo: timestamp('valid_to', { mode: 'date' }),

		createdAt: timestamp('created_at', { mode: 'date' }).notNull().defaultNow(),
		updatedAt: timestamp('updated_at', { mode: 'date' }).notNull().defaultNow(),
	},
	t => ({
		compositeUnq: uniqueIndex('sima_composite_unq').on(t.storeIntegrationId, t.accessType, t.platform, t.externalId),
		storeIntegrationIdx: index('sima_store_integration_id_idx').on(t.storeIntegrationId),
		platformIdx: index('sima_platform_idx').on(t.platform),
		activeIdx: index('sima_active_idx').on(t.active),
	}),
)

/**
 * `campaign_product_bindings` links a Campaign to specific Products or
 * Variants for ROAS attribution. TS-owned.
 *
 * Spec rule: a binding targets EITHER a product OR a specific variant
 * — never both. The runtime check lives in the
 * CreateCampaignProductBinding use case (Drizzle CHECK constraints are
 * awkward to express across the codegen pipeline, so we enforce in app
 * code and rely on the unique index to dedupe.)
 */
export const campaignProductBindings = marketingSchema.table(
	'campaign_product_bindings',
	{
		id: uuid('id').primaryKey().defaultRandom(),

		storeId: uuid('store_id').notNull(),
		campaignId: uuid('campaign_id').notNull(),

		// One of these is set; the other is NULL.
		productId: uuid('product_id'),
		variantId: uuid('variant_id'),

		createdAt: timestamp('created_at', { withTimezone: true }).notNull().defaultNow(),
		updatedAt: timestamp('updated_at', { withTimezone: true }).notNull().defaultNow(),
		version: integer('version').notNull().default(1),
	},
	t => ({
		// Dedupe: at most one binding per (campaign, product, variant)
		// triple. CAVEAT: Postgres default treats NULL as distinct from
		// other NULLs in unique indexes, so this index does NOT prevent
		// duplicate (campaignId, productId, NULL) rows on its own.
		// Application code (CreateCampaignProductBinding) must read-
		// check before write to enforce single-binding semantics; this
		// index is a defense-in-depth safety net for the fully-populated
		// (campaignId, productId, variantId) case where neither pointer
		// is NULL.
		bindingUnq: uniqueIndex('campaign_product_bindings_unq').on(t.campaignId, t.productId, t.variantId),
		storeIdx: index('campaign_product_bindings_store_id_idx').on(t.storeId),
		productIdx: index('campaign_product_bindings_product_id_idx').on(t.productId),
		variantIdx: index('campaign_product_bindings_variant_id_idx').on(t.variantId),
	}),
)

