import { pgSchema, uuid, text, timestamp, integer, boolean, jsonb, index, uniqueIndex } from 'drizzle-orm/pg-core'

/**
 * `notify` is BK Dash's BC10 Notifications schema.
 *
 * Distinct from polyglot's `notifications` pgSchema (which holds the
 * video-domain push device + push log tables for an unrelated
 * subscription concern). BK Dash's notifications are broader: order
 * alerts, sync errors, daily digests, invitations, integration-
 * disconnected warnings.
 *
 * Two tables:
 *   - `notifications`           — source notification rows
 *                                 (creator-bound; one per Send call).
 *   - `notification_deliveries` — per-recipient × channel fan-out rows
 *                                 (one per (notificationId, userId,
 *                                 channel) tuple — `readAt` stamped on
 *                                 mark-read).
 *
 * **File + TS-export naming:** filename `bkdash_notifications.ts` (the
 * underscore variant Drizzle expects) avoids the polyglot `notifications.ts`
 * collision. TS exports `bkdashNotifications` / `bkdashNotificationDeliveries`
 * avoid colliding with polyglot's barrel exports. PG schema name
 * `notify` is intentionally short — the schema namespace already
 * disambiguates from `notifications` (polyglot).
 *
 * **Conceptual model:** the notifications row is creator-bound (one
 * per Send call) and carries the content + metadata once; deliveries
 * fan it out across recipients × channels. This matches the BC10
 * BkdashNotification + BkdashNotificationDelivery entity split, and
 * differs from the iter-12-era recipient-bound model that this file
 * previously held — superseded by iter 313 to align with the
 * production entity contract.
 */
export const notifySchema = pgSchema('notify')

export const bkdashNotifications = notifySchema.table(
	'notifications',
	{
		id: uuid('id').primaryKey().defaultRandom(),

		title: text('title').notNull(),
		content: text('content').notNull(),

		// NotificationCategory enum value.
		category: text('category').notNull(),
		// NotificationOrigin enum value.
		origin: text('origin').notNull(),

		important: boolean('important').notNull().default(false),
		// MIME-style content type; defaults to text/plain. Used by the
		// app shell to decide whether to render the body as markdown,
		// html, etc.
		contentType: text('content_type').notNull().default('text/plain'),

		// Free-form per-category metadata (e.g. {entityId, entityType}
		// for an order-event notification). The entity schema validates
		// it as `Record<string, unknown>`.
		payload: jsonb('payload').notNull().default({}),

		// Nullable for global notifications (system announcements with
		// no store scope). Per-store notifications carry the storeId
		// here so list queries can filter by current-store.
		storeId: uuid('store_id'),

		// Audit pointer (no FK to users — User table is BetterAuth-owned
		// and we want notifications to survive user deletions for
		// audit trail purposes).
		createdByUserId: text('created_by_user_id').notNull(),

		createdAt: timestamp('created_at', { withTimezone: true }).notNull().defaultNow(),
		updatedAt: timestamp('updated_at', { withTimezone: true }).notNull().defaultNow(),
		version: integer('version').notNull().default(1),
	},
	t => ({
		// Per-store listings (T13 GetNotifications).
		storeIdx: index('notifications_store_id_idx').on(t.storeId),
		// Newest-first scans for the global digest job.
		createdAtIdx: index('notifications_created_at_idx').on(t.createdAt),
		categoryIdx: index('notifications_category_idx').on(t.category),
		originIdx: index('notifications_origin_idx').on(t.origin),
	}),
)

export const bkdashNotificationDeliveries = notifySchema.table(
	'notification_deliveries',
	{
		id: uuid('id').primaryKey().defaultRandom(),

		notificationId: uuid('notification_id')
			.notNull()
			.references(() => bkdashNotifications.id, { onDelete: 'cascade' }),

		// Audit pointer — same rationale as bkdashNotifications.createdByUserId.
		userId: text('user_id').notNull(),

		// NotificationChannel enum value (IN_APP | EMAIL | PUSH | …).
		channel: text('channel').notNull(),

		deliveredAt: timestamp('delivered_at', { withTimezone: true }).notNull(),
		readAt: timestamp('read_at', { withTimezone: true }),

		createdAt: timestamp('created_at', { withTimezone: true }).notNull().defaultNow(),
		updatedAt: timestamp('updated_at', { withTimezone: true }).notNull().defaultNow(),
		version: integer('version').notNull().default(1),
	},
	t => ({
		// Dedupe: at most one delivery per (notification, user, channel).
		notificationUserChannelUnq: uniqueIndex('notification_deliveries_notification_user_channel_unq').on(
			t.notificationId,
			t.userId,
			t.channel,
		),
		// Per-user inbox listings (T14 GetMyNotifications). Filter by
		// readAt IS NULL for the "unread" badge.
		userReadAtIdx: index('notification_deliveries_user_read_at_idx').on(t.userId, t.readAt),
		notificationIdx: index('notification_deliveries_notification_id_idx').on(t.notificationId),
	}),
)

