function withSubscriptions(
	testContainer: DependencyContainer,
	testBed: TestBed,
	subs: ActiveSubscription[],
): void {
	const subSvc = {
		getActiveSubscriptions: async () => subs,
		getSubscriptionById: async () => undefined,
	} as any
	testContainer.registerInstance(SubscriptionQueryService as any, subSvc)
	testContainer.registerInstance(
		PlanQuotaService as any,
		new PlanQuotaService(subSvc, testBed.resolve(StoreRepository)),
	)
}

