		expect(store?.name).toBe('Acme')
		expect(store?.reportingCurrency).toBe(CurrencyCode.BRL)
		// Store is bound to the mock subscription id.
		expect(store?.subscriptionId).toBe(MOCK_SUB_ID)

		const membership = await membershipRepo.findByStoreAndUser(out.storeId, userId)
		expect(membership?.role).toBe(Role.OWNER)

		const eventRepo = testBed.resolve(DomainEventRepository)
		const created = await eventRepo.findByType(StoreCreatedEvent)
		const prefs = await eventRepo.findByType(StorePreferencesCreatedEvent)
		const added = await eventRepo.findByType(StoreMemberAddedEvent)
		expect(created).toHaveLength(1)
		expect(prefs).toHaveLength(1)
		expect(added).toHaveLength(1)
		expect(created[0]!.payload.storeId).toBe(out.storeId)
		expect(created[0]!.payload.createdByUserId).toBe(userId)
		expect(added[0]!.payload.role).toBe(Role.OWNER)
	})

	it('throws STORE_QUOTA_EXCEEDED on the second CreateStore for a BASIC user', async () => {
		// Default ONE_BASIC_SUB — cap = 1.
		const useCase = testBed.resolve(CreateStore)
		const membershipRepo = testBed.resolve(StoreMembershipRepository)

		await useCase.execute({
			userId,
			name: 'First',
			reportingCurrency: CurrencyCode.USD,
			timezone: 'UTC',
		})

		let caught: unknown = null
		try {
			await useCase.execute({
				userId,
				name: 'Second',
				reportingCurrency: CurrencyCode.USD,
				timezone: 'UTC',
			})
		} catch (e) {
			caught = e
		}
		expect(caught).toBeInstanceOf(BaseError)
		expect((caught as BaseError).name).toBe('STORE_QUOTA_EXCEEDED')

		// Confirm second store never persisted.
		const memberships = await membershipRepo.findByUserId(userId)
		expect(memberships).toHaveLength(1)
	})

	it('throws NO_ACTIVE_SUBSCRIPTION when getActiveSubscriptions returns []', async () => {
		withSubscriptions(testContainer, testBed, [])
		const useCase = testBed.resolve(CreateStore)

		let caught: unknown = null
		try {
			await useCase.execute({
				userId,
				name: 'X',
				reportingCurrency: CurrencyCode.USD,
				timezone: 'UTC',
			})
		} catch (e) {
			caught = e
		}
		expect(caught).toBeInstanceOf(BaseError)
		expect((caught as BaseError).name).toBe('NO_ACTIVE_SUBSCRIPTION')
	})

	it('upgrading the plan tier raises the quota — INTERMEDIATE allows 3 stores', async () => {
		withSubscriptions(testContainer, testBed, [{ subscriptionId: '019e4d24-0000-7000-8000-000000000020', tier: PlanTier.INTERMEDIATE }])
		const useCase = testBed.resolve(CreateStore)

		await useCase.execute({ userId, name: 'A', reportingCurrency: CurrencyCode.USD, timezone: 'UTC' })
		await useCase.execute({ userId, name: 'B', reportingCurrency: CurrencyCode.USD, timezone: 'UTC' })
		await useCase.execute({ userId, name: 'C', reportingCurrency: CurrencyCode.USD, timezone: 'UTC' })

		const membershipRepo = testBed.resolve(StoreMembershipRepository)
		const memberships = await membershipRepo.findByUserId(userId)
		expect(memberships).toHaveLength(3)
	})

	it('rejects invalid timezone (entity invariant propagates)', async () => {
		const useCase = testBed.resolve(CreateStore)
		await expect(
			useCase.execute({
				userId,
				name: 'X',
				reportingCurrency: CurrencyCode.USD,
				timezone: 'not-valid',
			}),
		).rejects.toThrow(BaseError)
	})

	it('rejects empty name (entity invariant propagates)', async () => {
		const useCase = testBed.resolve(CreateStore)
		await expect(
			useCase.execute({
				userId,
				name: '   ',
				reportingCurrency: CurrencyCode.USD,
				timezone: 'UTC',
			}),
		).rejects.toThrow(BaseError)
	})

	// ── T8 cases ─────────────────────────────────────────────────────────────

	it('binds the new store to the highest-tier subscription with a free slot', async () => {
		const subBasicId = '019e4d24-0000-7000-8000-000000000010'
		const subAdvId = '019e4d24-0000-7000-8000-000000000011'
		withSubscriptions(testContainer, testBed, [
			{ subscriptionId: subBasicId, tier: PlanTier.BASIC },
			{ subscriptionId: subAdvId, tier: PlanTier.ADVANCED },
		])
		const usecase = testBed.resolve(CreateStore)
		const { storeId } = await usecase.execute({ userId, name: 'S', reportingCurrency: CurrencyCode.BRL, timezone: 'America/Sao_Paulo' })
		const store = await testBed.resolve(StoreRepository).findById(storeId)
		expect(store?.subscriptionId).toBe(subAdvId)
	})

	it('throws STORE_QUOTA_EXCEEDED when every active subscription is full', async () => {
		const subBasicId = '019e4d24-0000-7000-8000-000000000002'
		withSubscriptions(testContainer, testBed, [{ subscriptionId: subBasicId, tier: PlanTier.BASIC }])
		const usecase = testBed.resolve(CreateStore)
		// BASIC cap = 1; create the first store, then the second must fail.
		await usecase.execute({ userId, name: 'A', reportingCurrency: CurrencyCode.BRL, timezone: 'America/Sao_Paulo' })
		let caught: unknown = null
		try {
			await usecase.execute({ userId, name: 'B', reportingCurrency: CurrencyCode.BRL, timezone: 'America/Sao_Paulo' })
		} catch (e) {
			caught = e
		}
		expect(caught).toBeInstanceOf(BaseError)
		expect((caught as BaseError).name).toBe('STORE_QUOTA_EXCEEDED')
	})

	it('throws NO_ACTIVE_SUBSCRIPTION when the user has none', async () => {
		withSubscriptions(testContainer, testBed, [])
		const usecase = testBed.resolve(CreateStore)
		let caught: unknown = null
		try {
			await usecase.execute({ userId, name: 'X', reportingCurrency: CurrencyCode.BRL, timezone: 'America/Sao_Paulo' })
		} catch (e) {
			caught = e
		}
		expect(caught).toBeInstanceOf(BaseError)
		expect((caught as BaseError).name).toBe('NO_ACTIVE_SUBSCRIPTION')
	})
})

import { afterAll, beforeAll, beforeEach, describe, expect, it } from 'bun:test'
import { container, type DependencyContainer } from 'tsyringe-neo'
import { TestBed, testId } from '@test/support'
import { CurrencyCode } from '@bk-dash/contracts-typescript/wire/enums'
import { GetStorePreferencesSettings } from './GetStorePreferencesSettings'
import { UpdateStorePreferences } from './UpdateStorePreferences'
import { Store } from '../entities/Store'
import { StoreRepository } from '../repositories/StoreRepository'
import { OrderSamplingService } from '../services'

const ABSENT_STORE_ID = testId()

class HasOrdersStub extends OrderSamplingService {
	constructor(private readonly v: boolean) {
		super()
	}
	async hasOrdersForStore(_storeId: string): Promise<boolean> {
		return this.v
	}
}

describe('GetStorePreferencesSettings query use case (T09)', () => {
	let testBed: TestBed
	let testContainer: DependencyContainer
	let get: GetStorePreferencesSettings
	let update: UpdateStorePreferences
	let storeRepo: StoreRepository

	beforeAll(async () => {
		testContainer = container.createChildContainer()
		testContainer.register(OrderSamplingService as never, { useValue: new HasOrdersStub(false) })
		testBed = await TestBed.create('integration', { testContainer, ownerId: 'integration-tenant' })
		get = testBed.resolve(GetStorePreferencesSettings)
		update = testBed.resolve(UpdateStorePreferences)
		storeRepo = testBed.resolve(StoreRepository)
	})
	beforeEach(async () => {
		await testBed.reset()
	})
	afterAll(async () => {
		await testBed.destroy()
	})

	it('returns the prefs DTO from a freshly created store', async () => {
		const s = Store.create({
			name: 'Acme',
			reportingCurrency: CurrencyCode.USD,
			timezone: 'America/Sao_Paulo',
		})
		await storeRepo.save(s)

		const out = await get.execute({ storeId: s.id.value })
		expect(out).toMatchObject({
			storeId: s.id.value,
			reportingCurrency: CurrencyCode.USD,
			timezone: 'America/Sao_Paulo',
			showStoreNameInNotifications: true,
		})
		expect(typeof out.updatedAt).toBe('string')
	})

	it('reflects an update after UpdateStorePreferences runs', async () => {
		const s = Store.create({
			name: 'Acme',
			reportingCurrency: CurrencyCode.USD,
			timezone: 'UTC',
		})
		await storeRepo.save(s)

		await update.execute({
			storeId: s.id.value,
			updatedByUserId: testId('user', '1'),
			reportingCurrency: CurrencyCode.BRL,
			showStoreNameInNotifications: false,
		})

		const out = await get.execute({ storeId: s.id.value })
		expect(out.reportingCurrency).toBe(CurrencyCode.BRL)
		expect(out.showStoreNameInNotifications).toBe(false)
		expect(out.timezone).toBe('UTC')
	})

	it('throws STORE_NOT_FOUND for an absent storeId', async () => {
		await expect(get.execute({ storeId: ABSENT_STORE_ID })).rejects.toMatchObject({ name: 'STORE_NOT_FOUND' })
	})
})

