import { describe, expect, it } from 'bun:test'
import { AdSpendGroupBy, CurrencyCode } from '@bk-dash/contracts-typescript/wire/enums'
import { testId } from '@test/support'
import { AdSpendManual, AdSpendManualSchema } from './AdSpendManual'

describe('AdSpendManual entity', () => {
	it('static create() builds a manual ad-spend with default groupBy=DAILY', () => {
		const spend = AdSpendManual.create({
			storeId: 'store-1',
			currency: CurrencyCode.USD,
			startDate: new Date('2026-05-01T00:00:00.000Z'),
			endDate: new Date('2026-05-31T23:59:59.000Z'),
			spend: { amountCents: 100_00, currency: CurrencyCode.USD },
			name: 'Influencer campaign',
			createdByUserId: 'user-1',
		})
		expect(spend.storeId.value).toBe('store-1')
		expect(spend.platform).toBeUndefined()
		expect(spend.spend.amountCents).toBe(100_00)
		expect(spend.groupBy).toBe(AdSpendGroupBy.DAILY)
	})

	it('static create() accepts optional impressions/clicks/conversions metrics', () => {
		const spend = AdSpendManual.create({
			storeId: 'store-1',
			currency: CurrencyCode.USD,
			startDate: new Date('2026-05-01T00:00:00.000Z'),
			endDate: new Date('2026-05-01T23:59:59.000Z'),
			spend: { amountCents: 50_00, currency: CurrencyCode.USD },
			impressions: 1000,
			clicks: 50,
			conversions: 5,
			createdByUserId: 'user-1',
		})
		expect(spend.impressions).toBe(1000)
		expect(spend.clicks).toBe(50)
		expect(spend.conversions).toBe(5)
	})

	it('create() throws INVALID_DATE_RANGE when startDate > endDate via schema refine', () => {
		expect(() =>
			AdSpendManual.create({
				storeId: 'store-1',
				currency: CurrencyCode.USD,
				startDate: new Date('2026-05-31T00:00:00.000Z'),
				endDate: new Date('2026-05-01T00:00:00.000Z'),
				spend: { amountCents: 100, currency: CurrencyCode.USD },
				createdByUserId: 'user-1',
			}),
		).toThrow(expect.objectContaining({ name: 'INVALID_DATE_RANGE' }))
	})
})

describe('AdSpendManualSchema (SPEC-16)', () => {
	const base = {
		storeId: testId('store', '1'),
		platform: 'META' as const,
		currency: 'USD' as const,
		startDate: new Date('2026-04-20T23:00:00.000Z'),
		endDate: new Date('2026-04-20T23:59:59.000Z'),
		groupBy: 'HOURLY' as const,
		spend: { amountCents: 1564, currency: 'USD' as const },
		createdByUserId: 'user-1',
	}

	it('accepts a valid manual record with datetime dates', () => {
		expect(AdSpendManualSchema.safeParse(base).success).toBe(true)
	})

	it('rejects bare date string for startDate', () => {
		const r = AdSpendManualSchema.safeParse({ ...base, startDate: '2026-04-20' })
		expect(r.success).toBe(false)
	})

	it('rejects MANUAL as platform value', () => {
		const r = AdSpendManualSchema.safeParse({ ...base, platform: 'MANUAL' })
		expect(r.success).toBe(false)
	})

	it('accepts undefined platform', () => {
		const r = AdSpendManualSchema.safeParse({ ...base, platform: undefined })
		expect(r.success).toBe(true)
	})

	it('rejects startDate > endDate via schema refine', () => {
		const r = AdSpendManualSchema.safeParse({
			...base,
			startDate: new Date('2026-04-20T23:59:59.000Z'),
			endDate: new Date('2026-04-20T23:00:00.000Z'),
		})
		expect(r.success).toBe(false)
	})

	it('accepts startDate === endDate', () => {
		const r = AdSpendManualSchema.safeParse({
			...base,
			startDate: new Date('2026-04-20T23:00:00.000Z'),
			endDate: new Date('2026-04-20T23:00:00.000Z'),
		})
		expect(r.success).toBe(true)
	})

	it('spend is parsed via MonetaryAmountSchema (nonnegative int)', () => {
		// z.instance(MonetaryAmount) calls new MonetaryAmount() which throws on
		// invalid input — Zod v4 does not suppress errors thrown inside transforms.
		let caught: unknown = null
		try {
			AdSpendManualSchema.safeParse({ ...base, spend: { amountCents: -1, currency: 'USD' } })
		} catch (e) {
			caught = e
		}
		expect(caught).not.toBeNull()
	})
})

import { describe, expect, it } from 'bun:test'
import { CampaignProductBinding } from './CampaignProductBinding'

describe('CampaignProductBinding entity', () => {
	it('static create() builds with boundAt stamped to now', () => {
		const beforeMs = Date.now()
		const binding = CampaignProductBinding.create({
			storeId: 'store-1',
			campaignId: 'campaign-1',
			productIds: ['p-1', 'p-2'],
			variantIds: ['v-1'],
			createdByUserId: 'user-1',
		})
		const afterMs = Date.now()

		expect(binding.storeId.value).toBe('store-1')
		expect(binding.campaignId.value).toBe('campaign-1')
		expect(binding.productIds.map(id => id.value)).toEqual(['p-1', 'p-2'])
		expect(binding.variantIds.map(id => id.value)).toEqual(['v-1'])
		expect(binding.createdByUserId.value).toBe('user-1')
		expect(new Date(binding.boundAt).getTime()).toBeGreaterThanOrEqual(beforeMs)
		expect(new Date(binding.boundAt).getTime()).toBeLessThanOrEqual(afterMs)
	})

	it('accepts empty productIds and variantIds arrays', () => {
		const binding = CampaignProductBinding.create({
			storeId: 'store-1',
			campaignId: 'campaign-1',
			productIds: [],
			variantIds: [],
			createdByUserId: 'user-1',
		})
		expect(binding.productIds).toEqual([])
		expect(binding.variantIds).toEqual([])
	})
})

import { describe, expect, it } from 'bun:test'
import { testId } from '@test/support'
import { ManualAdSpendRecordedEventSchema } from './ManualAdSpendRecordedEvent'

/**
 * SPEC-16: Verify that ManualAdSpendRecordedEvent enforces datetime dates
 * via AdSpendSchema (which now uses z.date()). Since the event
 * embeds AdSpendSchema directly, these guarantees flow through automatically.
 * We test the payload schema shape directly.
 */
describe('ManualAdSpendRecordedEventSchema (SPEC-16)', () => {
	// Extract the payload schema from the domain-event wrapper.
	const payloadSchema = ManualAdSpendRecordedEventSchema.shape.payload

	const validAdSpend = {
		storeId: testId('store', '1'),
		platform: 'META',
		currency: 'USD',
		startDate: new Date('2026-05-01T00:00:00.000Z'),
		endDate: new Date('2026-05-31T23:59:59.000Z'),
		groupBy: 'DAILY',
		spend: { amountCents: 1000, currency: 'USD' },
		createdByUserId: 'user-1',
	}

	it('accepts datetime startDate/endDate in embedded adSpend', () => {
		expect(payloadSchema.safeParse({ adSpend: validAdSpend }).success).toBe(true)
	})

	it('rejects bare date-only startDate in embedded adSpend', () => {
		const r = payloadSchema.safeParse({
			adSpend: { ...validAdSpend, startDate: '2026-05-01' },
		})
		expect(r.success).toBe(false)
	})
})

import { afterAll, beforeAll, beforeEach, describe, expect, it } from 'bun:test'
import { container, type DependencyContainer } from 'tsyringe-neo'
import { TestBed, testId } from '@test/support'
import { AdSpendGroupBy, CurrencyCode } from '@bk-dash/contracts-typescript/wire/enums'
import { AdSpendManual } from '../../entities/AdSpendManual'
import { AdSpendManualRepository } from './AdSpendManualRepository'

const STORE_A = testId('store', 'a')
const STORE_B = testId('store', 'b')
const USER = testId('user', '1')

describe('DrizzleAdSpendManualRepository', () => {
	let testBed: TestBed
	let testContainer: DependencyContainer
	let repo: AdSpendManualRepository

	beforeAll(async () => {
		testContainer = container.createChildContainer()
		testBed = await TestBed.create('integration', { testContainer, ownerId: 'integration-tenant' })
		repo = testBed.resolve(AdSpendManualRepository)
	})
	beforeEach(async () => {
		await testBed.reset()
	})
	afterAll(async () => {
		await testBed.destroy()
	})

	function buildManual(opts: {
		storeId?: string
		startDate?: string
		endDate?: string
		amountCents?: number
		currency?: CurrencyCode
		name?: string
	}): AdSpendManual {
		return AdSpendManual.create({
			storeId: opts.storeId ?? STORE_A,
			currency: opts.currency ?? CurrencyCode.USD,
			startDate: new Date(opts.startDate ?? '2026-05-01T00:00:00.000Z'),
			endDate: new Date(opts.endDate ?? '2026-05-31T23:59:59.000Z'),
			spend: { amountCents: opts.amountCents ?? 10_000, currency: opts.currency ?? CurrencyCode.USD },
			name: opts.name,
			createdByUserId: USER,
		})
	}

	describe('save + findById', () => {
		it('round-trips a MANUAL AdSpendManual through Drizzle', async () => {
			const entity = buildManual({ amountCents: 25_000, name: 'May spend' })
			await repo.save(entity)

			const fetched = await repo.findById(entity.id.value)
			expect(fetched).toBeDefined()
			expect(fetched?.platform).toBeUndefined()
			expect(fetched?.spend.amountCents).toBe(25_000)
			expect(fetched?.spend.currency).toBe(CurrencyCode.USD)
			expect(fetched?.startDate).toEqual(new Date('2026-05-01T00:00:00.000Z'))
			expect(fetched?.endDate).toEqual(new Date('2026-05-31T23:59:59.000Z'))
			expect(fetched?.name).toBe('May spend')
			expect(fetched?.createdByUserId.value).toBe(USER)
			expect(fetched?.groupBy).toBe(AdSpendGroupBy.DAILY)
		})

		it('returns undefined when no row matches', async () => {
			const r = await repo.findById(testId('not', 'found'))
			expect(r).toBeUndefined()
		})

		it('UPSERT semantics — re-saving the same entity bumps version + persists new fields', async () => {
			const entity = buildManual({ amountCents: 10_000, name: 'original' })
			await repo.save(entity)

			entity.updateManual({ spend: { amountCents: 20_000, currency: CurrencyCode.USD }, name: 'updated' })
			await repo.save(entity)

			const fetched = await repo.findById(entity.id.value)
			expect(fetched?.spend.amountCents).toBe(20_000)
			expect(fetched?.name).toBe('updated')
			expect(fetched?.version).toBeGreaterThan(1)
		})
	})

	describe('breakdown', () => {
		it('returns total=0 + empty items when no rows match', async () => {
			const r = await repo.breakdown({
				storeId: STORE_A,
				from: new Date('2026-05-01T00:00:00.000Z'),
				to: new Date('2026-05-31T23:59:59.999Z'),
				groupBy: AdSpendGroupBy.DAILY,
				page: 1,
				limit: 10,
			})
			expect(r.total).toBe(0)
			expect(r.items).toEqual([])
		})

		it('filters by storeId (cross-store leak protection)', async () => {
			await repo.save(buildManual({ storeId: STORE_A, name: 'A' }))
			await repo.save(buildManual({ storeId: STORE_B, name: 'B' }))

			const r = await repo.breakdown({
				storeId: STORE_A,
				from: new Date('2026-05-01T00:00:00.000Z'),
				to: new Date('2026-05-31T23:59:59.999Z'),
				groupBy: AdSpendGroupBy.DAILY,
				page: 1,
				limit: 10,
			})
			expect(r.total).toBe(1)
			expect(r.items[0]?.name).toBe('A')
		})

		it('filters by date-range overlap on (startDate..endDate)', async () => {
			await repo.save(buildManual({ startDate: '2026-04-01T00:00:00.000Z', endDate: '2026-04-30T23:59:59.000Z', name: 'apr' }))
			await repo.save(buildManual({ startDate: '2026-05-01T00:00:00.000Z', endDate: '2026-05-31T23:59:59.000Z', name: 'may' }))
			await repo.save(buildManual({ startDate: '2026-06-01T00:00:00.000Z', endDate: '2026-06-30T23:59:59.000Z', name: 'jun' }))

			const r = await repo.breakdown({
				storeId: STORE_A,
				from: new Date('2026-05-01T00:00:00.000Z'),
				to: new Date('2026-05-31T23:59:59.999Z'),
				groupBy: AdSpendGroupBy.DAILY,
				page: 1,
				limit: 10,
			})
			expect(r.total).toBe(1)
			expect(r.items[0]?.name).toBe('may')
		})

		it('paginates newest-first by startDate', async () => {
			await repo.save(buildManual({ startDate: '2026-05-01T00:00:00.000Z', endDate: '2026-05-01T23:59:59.000Z', name: 'a' }))
			await repo.save(buildManual({ startDate: '2026-05-10T00:00:00.000Z', endDate: '2026-05-10T23:59:59.000Z', name: 'b' }))
			await repo.save(buildManual({ startDate: '2026-05-20T00:00:00.000Z', endDate: '2026-05-20T23:59:59.000Z', name: 'c' }))

			const r = await repo.breakdown({
				storeId: STORE_A,
				from: new Date('2026-05-01T00:00:00.000Z'),
				to: new Date('2026-05-31T23:59:59.999Z'),
				groupBy: AdSpendGroupBy.DAILY,
				page: 1,
				limit: 10,
			})
			expect(r.total).toBe(3)
			expect(r.items.map(i => i.name)).toEqual(['c', 'b', 'a'])
		})

		it('paginates: total reflects unpaged match count', async () => {
			for (let i = 0; i < 5; i++) {
				await repo.save(
					buildManual({
						startDate: `2026-05-0${i + 1}T00:00:00.000Z`,
						endDate: `2026-05-0${i + 1}T23:59:59.000Z`,
						name: `s${i}`,
					}),
				)
			}

			const page1 = await repo.breakdown({
				storeId: STORE_A,
				from: new Date('2026-05-01T00:00:00.000Z'),
				to: new Date('2026-05-31T23:59:59.999Z'),
				groupBy: AdSpendGroupBy.DAILY,
				page: 1,
				limit: 2,
			})
			const page3 = await repo.breakdown({
				storeId: STORE_A,
				from: new Date('2026-05-01T00:00:00.000Z'),
				to: new Date('2026-05-31T23:59:59.999Z'),
				groupBy: AdSpendGroupBy.DAILY,
				page: 3,
				limit: 2,
			})

			expect(page1.total).toBe(5)
			expect(page1.items).toHaveLength(2)
			expect(page3.items).toHaveLength(1)
		})

		it('round-trips bindings array verbatim', async () => {
			const entity = AdSpendManual.create({
				storeId: STORE_A,
				currency: CurrencyCode.USD,
				startDate: new Date('2026-05-01T00:00:00.000Z'),
				endDate: new Date('2026-05-31T23:59:59.000Z'),
				spend: { amountCents: 5000, currency: CurrencyCode.USD },
				bindings: [{ productId: 'p-1' }, { variantId: 'v-2' }, { productId: 'p-3', variantId: 'v-3' }],
				createdByUserId: USER,
			})
			await repo.save(entity)

			const fetched = await repo.findById(entity.id.value)
			expect(fetched?.bindings).toEqual([{ productId: 'p-1' }, { variantId: 'v-2' }, { productId: 'p-3', variantId: 'v-3' }])
		})
	})

	describe('delete', () => {
		it('removes the row + subsequent findById returns undefined', async () => {
			const entity = buildManual({ name: 'to-delete' })
			await repo.save(entity)
			await repo.delete(entity.id.value)
			expect(await repo.findById(entity.id.value)).toBeUndefined()
		})
	})
})

import { afterAll, beforeAll, beforeEach, describe, expect, it } from 'bun:test'
import { container, type DependencyContainer } from 'tsyringe-neo'
import { TestBed, testId } from '@test/support'
import { DomainEventRepository } from '@bk-dash/core-typescript'
import { CurrencyCode } from '@bk-dash/contracts-typescript/wire/enums'
import { RecordManualAdSpend } from './RecordManualAdSpend'
import { UpdateManualAdSpend } from './UpdateManualAdSpend'
import { DeleteManualAdSpend } from './DeleteManualAdSpend'
import { AdSpendManualRepository } from '../repositories/AdSpendManualRepository'
import { ManualAdSpendDeletedEvent, ManualAdSpendRecordedEvent, ManualAdSpendUpdatedEvent } from '../events'

const STORE = testId('store', '1')
const USER = testId('user', '1')

describe('Manual AdSpend (C33 + C34 + C35)', () => {
	let testBed: TestBed
	let testContainer: DependencyContainer
	let record: RecordManualAdSpend
	let update: UpdateManualAdSpend
	let del: DeleteManualAdSpend
	let repo: AdSpendManualRepository

	beforeAll(async () => {
		testContainer = container.createChildContainer()
		testBed = await TestBed.create('integration', { testContainer, ownerId: 'integration-tenant' })
		record = testBed.resolve(RecordManualAdSpend)
		update = testBed.resolve(UpdateManualAdSpend)
		del = testBed.resolve(DeleteManualAdSpend)
		repo = testBed.resolve(AdSpendManualRepository)
	})
	beforeEach(async () => {
		await testBed.reset()
	})
	afterAll(async () => {
		await testBed.destroy()
	})

	async function readRecordedEvents() {
		return testBed.resolve(DomainEventRepository).findByType(ManualAdSpendRecordedEvent)
	}
	async function readUpdatedEvents() {
		return testBed.resolve(DomainEventRepository).findByType(ManualAdSpendUpdatedEvent)
	}
	async function readDeletedEvents() {
		return testBed.resolve(DomainEventRepository).findByType(ManualAdSpendDeletedEvent)
	}

	describe('RecordManualAdSpend (C33)', () => {
		it('persists a MANUAL AdSpendManual + emits ManualAdSpendRecordedEvent', async () => {
			const out = await record.execute({
				userId: USER,
				storeId: STORE,
				startDate: new Date('2026-05-01T00:00:00.000Z'),
				endDate: new Date('2026-05-31T00:00:00.000Z'),
				currency: CurrencyCode.USD,
				amountCents: 10_000,
				description: 'May spend',
			})

			expect(out.adSpendId).toMatch(/^[0-9a-f-]{36}$/)
			const saved = await repo.findById(out.adSpendId)
			expect(saved?.platform).toBeUndefined()
			expect(saved?.spend.amountCents).toBe(10_000)
			expect(saved?.createdByUserId.value).toBe(USER)

			const emitted = await readRecordedEvents()
			expect(emitted).toHaveLength(1)
			expect(emitted[0]!.payload.adSpend).toBeDefined()
			expect(emitted[0]!.payload.adSpend.spend.amountCents).toBe(10_000)
		})

		it('propagates INVALID_DATE_RANGE when startDate > endDate', async () => {
			await expect(
				record.execute({
					userId: USER,
					storeId: STORE,
					startDate: new Date('2026-06-30T00:00:00.000Z'),
					endDate: new Date('2026-06-01T00:00:00.000Z'),
					currency: CurrencyCode.USD,
					amountCents: 100,
				}),
			).rejects.toMatchObject({ name: 'INVALID_DATE_RANGE' })
		})
	})

	describe('UpdateManualAdSpend (C34)', () => {
		async function seedManual(): Promise<string> {
			const { adSpendId } = await record.execute({
				userId: USER,
				storeId: STORE,
				startDate: new Date('2026-05-01T00:00:00.000Z'),
				endDate: new Date('2026-05-31T00:00:00.000Z'),
				currency: CurrencyCode.USD,
				amountCents: 5_000,
			})
			return adSpendId
		}

		it('updates name + description + emits with changedFields', async () => {
			const adSpendId = await seedManual()

			await update.execute({ userId: USER, adSpendId, name: 'new', description: 'updated' })

			const saved = await repo.findById(adSpendId)
			expect(saved?.name).toBe('new')
			expect(saved?.description).toBe('updated')

			const emitted = await readUpdatedEvents()
			expect(emitted).toHaveLength(1)
			expect(emitted[0]!.payload.adSpend).toBeDefined()
			expect(emitted[0]!.payload.adSpend.name).toBe('new')
		})

		it('updates spend (amountCents only — uses existing currency)', async () => {
			const adSpendId = await seedManual()

			await update.execute({ userId: USER, adSpendId, amountCents: 9_999 })

			const saved = await repo.findById(adSpendId)
			expect(saved?.spend.amountCents).toBe(9_999)
			expect(saved?.spend.currency).toBe(CurrencyCode.USD) // preserved
		})

		it('emits ManualAdSpendUpdatedEvent even when no fields supplied (always-publish)', async () => {
			const adSpendId = await seedManual()
			await update.execute({ userId: USER, adSpendId })
			const updated = await readUpdatedEvents()
			expect(updated).toHaveLength(1)
			expect(updated[0]!.payload.adSpend).toBeDefined()
		})

		it('throws AD_SPEND_NOT_FOUND on missing id', async () => {
			await expect(update.execute({ userId: USER, adSpendId: testId(), name: 'x' })).rejects.toMatchObject({ name: 'AD_SPEND_NOT_FOUND' })
		})
	})

	describe('DeleteManualAdSpend (C35)', () => {
		it('hard-deletes the MANUAL AdSpendManual + emits ManualAdSpendDeletedEvent', async () => {
			const { adSpendId } = await record.execute({
				userId: USER,
				storeId: STORE,
				startDate: new Date('2026-05-01T00:00:00.000Z'),
				endDate: new Date('2026-05-31T00:00:00.000Z'),
				currency: CurrencyCode.USD,
				amountCents: 5_000,
			})

			await del.execute({ userId: USER, adSpendId })

			expect(await repo.findById(adSpendId)).toBeUndefined()
			const emitted = await readDeletedEvents()
			expect(emitted).toHaveLength(1)
			expect(emitted[0]!.payload.adSpendId).toBe(adSpendId)
		})

		it('throws AD_SPEND_NOT_FOUND on missing id', async () => {
			await expect(del.execute({ userId: USER, adSpendId: testId() })).rejects.toMatchObject({ name: 'AD_SPEND_NOT_FOUND' })
		})
	})
})

