import { describe, expect, it } from 'bun:test'
import { OrderOverride } from './OrderOverride'
import { BaseError } from '@bk-dash/core-typescript'
import { PaymentStatus, PaymentMethod, CurrencyCode } from '@bk-dash/contracts-typescript/wire'

describe('OrderOverride aggregate', () => {
	it('creates with empty fields by default', () => {
		const override = OrderOverride.create({
			storeId: 'store-1',
			orderId: 'order-1',
			storeIntegrationExternalId: 'shopify.mystore.com',
			fields: {},
		})
		expect(override.orderId.value).toBe('order-1')
		expect(override.storeId.value).toBe('store-1')
		expect(override.storeIntegrationExternalId).toBe('shopify.mystore.com')
		expect(override.fields).toEqual({})
	})

	it('creates with valid fields', () => {
		const override = OrderOverride.create({
			storeId: 'store-1',
			orderId: 'order-1',
			storeIntegrationExternalId: 'shopify.mystore.com',
			fields: {
				paymentStatus: PaymentStatus.PAID,
				paymentMethod: PaymentMethod.CREDIT_CARD,
				revenue: { amountCents: 10000, currency: CurrencyCode.BRL },
			},
		})
		expect(override.fields.paymentStatus).toBe(PaymentStatus.PAID)
		expect(override.fields.revenue?.amountCents).toBe(10000)
	})

	it('mergeFields shallow-merges and updates updatedByUserId', () => {
		const override = OrderOverride.create({
			storeId: 'store-1',
			orderId: 'order-1',
			storeIntegrationExternalId: 'shopify.mystore.com',
			fields: { paymentStatus: PaymentStatus.PENDING },
		})
		override.mergeFields({ paymentMethod: PaymentMethod.PIX })
		expect(override.fields.paymentStatus).toBe(PaymentStatus.PENDING)
		expect(override.fields.paymentMethod).toBe(PaymentMethod.PIX)
	})

	it('throws INVALID_ORDER_OVERRIDE_FIELDS for invalid fields shape', () => {
		expect(() =>
			OrderOverride.create({
				storeId: 'store-1',
				orderId: 'order-1',
				storeIntegrationExternalId: 'shopify.mystore.com',
				fields: { bogusField: 'bad' } as any,
				updatedByUserId: 'user-1',
			}),
		).toThrow(BaseError)
	})

	it('rejects invalid productCostByLine shape', () => {
		expect(() =>
			OrderOverride.create({
				storeId: 'store-1',
				orderId: 'order-1',
				storeIntegrationExternalId: 'shopify.mystore.com',
				fields: { productCostByLine: [{ lineId: '', cost: { amountCents: -1, currency: CurrencyCode.BRL } }] },
				updatedByUserId: 'user-1',
			}),
		).toThrow()
	})
})

