import { describe, expect, it } from 'bun:test'
import { testId } from '@test/support'
import { ManualAdSpendRecordedEventSchema } from './ManualAdSpendRecordedEvent'

/**
 * SPEC-16: Verify that ManualAdSpendRecordedEvent enforces datetime dates
 * via AdSpendSchema (which now uses z.date()). Since the event
 * embeds AdSpendSchema directly, these guarantees flow through automatically.
 * We test the payload schema shape directly.
 */
describe('ManualAdSpendRecordedEventSchema (SPEC-16)', () => {
	// Extract the payload schema from the domain-event wrapper.
	const payloadSchema = ManualAdSpendRecordedEventSchema.shape.payload

	const validAdSpend = {
		storeId: testId('store', '1'),
		platform: 'META',
		currency: 'USD',
		startDate: new Date('2026-05-01T00:00:00.000Z'),
		endDate: new Date('2026-05-31T23:59:59.000Z'),
		groupBy: 'DAILY',
		spend: { amountCents: 1000, currency: 'USD' },
		createdByUserId: 'user-1',
	}

	it('accepts datetime startDate/endDate in embedded adSpend', () => {
		expect(payloadSchema.safeParse({ adSpend: validAdSpend }).success).toBe(true)
	})

	it('rejects bare date-only startDate in embedded adSpend', () => {
		const r = payloadSchema.safeParse({
			adSpend: { ...validAdSpend, startDate: '2026-05-01' },
		})
		expect(r.success).toBe(false)
	})
})

import { afterAll, beforeAll, beforeEach, describe, expect, it } from 'bun:test'
import { container, type DependencyContainer } from 'tsyringe-neo'
import { TestBed, testId, givenStore } from '@test/support'
import { DomainEventRepository } from '@bk-dash/core-typescript'
import { CurrencyCode } from '@bk-dash/contracts-typescript/wire/enums'
import { UpdateStoreSettings } from './UpdateStoreSettings'
import { StoreRepository } from '../repositories/StoreRepository'
import { StoreSettingsUpdatedEvent } from '../events'

const UPDATER_ID = testId('user', '99')

describe('UpdateStoreSettings use case (C13)', () => {
	let testBed: TestBed
	let testContainer: DependencyContainer
	let useCase: UpdateStoreSettings

	beforeAll(async () => {
		testContainer = container.createChildContainer()
		testBed = await TestBed.create('integration', { testContainer, ownerId: 'integration-tenant' })
		useCase = testBed.resolve(UpdateStoreSettings)
	})
	beforeEach(async () => {
		await testBed.reset()
	})
	afterAll(async () => {
		await testBed.destroy()
	})

	async function readEvents() {
		return testBed.resolve(DomainEventRepository).findByType(StoreSettingsUpdatedEvent)
	}

	it('partial update emits StoreSettingsUpdated with changedFields', async () => {
		const store = await givenStore(testBed, { name: 'Acme', reportingCurrency: CurrencyCode.USD, timezone: 'UTC' })
		const storeId = store.id.value
		await useCase.execute({
			storeId,
			name: 'Acme Co',
			email: 'hello@acme.test',
		})

		const reloaded = await testBed.resolve(StoreRepository).findById(storeId)
		expect(reloaded?.name).toBe('Acme Co')
		// `email` is in-memory only — tenancy.stores has no email column
		// (iter-70 in-memory-only fields). The use case still tracks the
		// change for the changedFields event payload below.

		const evts = await readEvents()
		expect(evts).toHaveLength(1)
		expect(evts[0]!.payload.store.name).toBe('Acme Co')
	})

	it('empty input → emits StoreSettingsUpdatedEvent (always-publish)', async () => {
		const { id } = await givenStore(testBed, { name: 'Acme', reportingCurrency: CurrencyCode.USD, timezone: 'UTC' })
		const storeId = id.value
		await useCase.execute({ storeId })

		const evts = await readEvents()
		expect(evts).toHaveLength(1)
	})

	it('same value → emits StoreSettingsUpdatedEvent (idempotent re-publish)', async () => {
		const { id } = await givenStore(testBed, { name: 'Acme', reportingCurrency: CurrencyCode.USD, timezone: 'UTC' })
		const storeId = id.value
		await useCase.execute({ storeId, name: 'Acme' })

		const evts = await readEvents()
		expect(evts).toHaveLength(1)
		expect(evts[0]!.payload.store.name).toBe('Acme')
	})

	it('throws STORE_NOT_FOUND for unknown storeId', async () => {
		await expect(
			useCase.execute({
				storeId: testId('store', '0'),
				name: 'X',
			}),
		).rejects.toMatchObject({ name: 'STORE_NOT_FOUND' })
	})
})

