import { describe, expect, it, beforeAll, afterAll, beforeEach } from 'bun:test'
import { container, type DependencyContainer } from 'tsyringe-neo'
import { TestBed } from '@test/support'
import { Id } from '@bk-dash/core-typescript'
import { OrderOverride } from '../../entities/OrderOverride'
import { DrizzleOrderOverrideRepository } from './DrizzleOrderOverrideRepository'
import { PaymentStatus, CurrencyCode } from '@bk-dash/contracts-typescript/wire'

// Use deterministic UUIDs for stable test IDs
const ORDER_AAA = Id.fromSeed('test', 'order', 'aaa').value
const ORDER_BBB = Id.fromSeed('test', 'order', 'bbb').value
const ORDER_CCC = Id.fromSeed('test', 'order', 'ccc').value
const ORDER_VER = Id.fromSeed('test', 'order', 'ver').value
const EXT_ID = 'shopify.store.com'

let testBed: TestBed
let testContainer: DependencyContainer

beforeAll(async () => {
	testContainer = container.createChildContainer()
	testBed = await TestBed.create('integration', { testContainer, ownerId: 'integration-tenant' })
})

beforeEach(async () => {
	await testBed.reset()
})

afterAll(async () => {
	await testBed.destroy()
})

function makeOverride(orderId = ORDER_AAA, externalId = EXT_ID) {
	return OrderOverride.create({
		storeId: Id.fromSeed('test', 'store', '1').value,
		orderId,
		storeIntegrationExternalId: externalId,
		fields: { paymentStatus: PaymentStatus.PAID },
	})
}

describe('DrizzleOrderOverrideRepository', () => {
	it('findByPin returns undefined when absent', async () => {
		const repo = testBed.resolve(DrizzleOrderOverrideRepository)
		const result = await repo.findByPin(Id.fromSeed('no', 'order').value, 'no-ext')
		expect(result).toBeUndefined()
	})

	it('save + findByPin round-trips all fields', async () => {
		const repo = testBed.resolve(DrizzleOrderOverrideRepository)
		const override = OrderOverride.create({
			storeId: Id.fromSeed('test', 'store', '1').value,
			orderId: ORDER_BBB,
			storeIntegrationExternalId: EXT_ID,
			fields: {
				paymentStatus: PaymentStatus.PAID,
				revenue: { amountCents: 9900, currency: CurrencyCode.BRL },
			},
		})
		await repo.save(override)

		const found = await repo.findByPin(ORDER_BBB, EXT_ID)
		expect(found).toBeDefined()
		expect(found!.fields.paymentStatus).toBe(PaymentStatus.PAID)
		expect(found!.fields.revenue?.amountCents).toBe(9900)
		expect(found!.fields.revenue?.currency).toBe(CurrencyCode.BRL)
	})

	it('save UPSERTs on composite PK — second call overwrites, not duplicates', async () => {
		const repo = testBed.resolve(DrizzleOrderOverrideRepository)
		const override = makeOverride()
		await repo.save(override)

		// Mutate and save again
		override.mergeFields({ paymentStatus: PaymentStatus.REFUNDED })
		await repo.save(override)

		const found = await repo.findByPin(ORDER_AAA, EXT_ID)
		expect(found).toBeDefined()
		expect(found!.fields.paymentStatus).toBe(PaymentStatus.REFUNDED)
	})

	it('version bumps on each save', async () => {
		const repo = testBed.resolve(DrizzleOrderOverrideRepository)
		const override = makeOverride(ORDER_VER, 'ext-ver')
		expect(override.version).toBe(1)
		await repo.save(override)
		expect(override.version).toBe(2)
		await repo.save(override)
