import { beforeEach, describe, expect, it } from 'bun:test'
import { PaymentStatus, CurrencyCode } from '@bk-dash/contracts-typescript/wire/enums'
import { testId } from '@test/support'
import { OrderOverride } from '../../entities/OrderOverride'
import { MockOrderOverrideRepository } from './MockOrderOverrideRepository'
import type { OrderOverrideFieldsInput } from '../../objects/OrderOverrideFields'

const STORE = testId('store', '1')
const USER = 'user-1'

function makeOverride(opts: { orderId: string; externalId: string; fields?: OrderOverrideFieldsInput }): OrderOverride {
	return OrderOverride.create({
		storeId: STORE,
		orderId: opts.orderId,
		storeIntegrationExternalId: opts.externalId,
		fields: opts.fields ?? defaultFields(),
		updatedByUserId: USER,
	})
}

function defaultFields(): OrderOverrideFieldsInput {
	return {
		paymentStatus: PaymentStatus.PAID,
		revenue: { amountCents: 5000, currency: CurrencyCode.USD },
	}
}

describe('MockOrderOverrideRepository', () => {
	let repo: MockOrderOverrideRepository

	beforeEach(() => {
		repo = new MockOrderOverrideRepository()
	})

	it('findByPin returns the seeded override', async () => {
		const o = makeOverride({ orderId: 'order-1', externalId: 'shop.myshopify.com' })
		repo.seed(o)
		const found = await repo.findByPin('order-1', 'shop.myshopify.com')
		expect(found?.orderId.value).toBe('order-1')
	})

	it('findByPin discriminates by storeIntegrationExternalId (same orderId, different shops)', async () => {
		repo.seed(makeOverride({ orderId: 'order-2', externalId: 'shop-a.myshopify.com' }))
		repo.seed(makeOverride({ orderId: 'order-2', externalId: 'shop-b.myshopify.com' }))

		const a = await repo.findByPin('order-2', 'shop-a.myshopify.com')
		const b = await repo.findByPin('order-2', 'shop-b.myshopify.com')
		const miss = await repo.findByPin('order-2', 'shop-c.myshopify.com')

		expect(a?.storeIntegrationExternalId).toBe('shop-a.myshopify.com')
		expect(b?.storeIntegrationExternalId).toBe('shop-b.myshopify.com')
		expect(miss).toBeUndefined()
	})

	it('save increments version and persists by (orderId, externalId)', async () => {
		const o = makeOverride({ orderId: 'order-3', externalId: 'shop.myshopify.com' })
		const initialVersion = o.version
		await repo.save(o)
		expect(o.version).toBe(initialVersion + 1)
		const found = await repo.findByPin('order-3', 'shop.myshopify.com')
		expect(found?.version).toBe(initialVersion + 1)
	})

	it('delete by orderId removes every shop variant', async () => {
		repo.seed(makeOverride({ orderId: 'order-4', externalId: 'shop-a.myshopify.com' }))
		repo.seed(makeOverride({ orderId: 'order-4', externalId: 'shop-b.myshopify.com' }))
		repo.seed(makeOverride({ orderId: 'order-5', externalId: 'shop-a.myshopify.com' }))

		await repo.delete('order-4')

		expect(await repo.findByPin('order-4', 'shop-a.myshopify.com')).toBeUndefined()
		expect(await repo.findByPin('order-4', 'shop-b.myshopify.com')).toBeUndefined()
		expect(await repo.findByPin('order-5', 'shop-a.myshopify.com')).toBeDefined()
	})

	it('clear empties the store', async () => {
		repo.seed(makeOverride({ orderId: 'order-6', externalId: 'shop.myshopify.com' }))
		repo.clear()
		expect(await repo.findByPin('order-6', 'shop.myshopify.com')).toBeUndefined()
	})
})

