import { afterAll, beforeAll, beforeEach, describe, expect, it } from 'bun:test'
import { container, type DependencyContainer } from 'tsyringe-neo'
import { TestBed, testId } from '@test/support'
import { CurrencyCode } from '@bk-dash/contracts-typescript/wire/enums'
import { GetStorePreferencesSettings } from './GetStorePreferencesSettings'
import { UpdateStorePreferences } from './UpdateStorePreferences'
import { Store } from '../entities/Store'
import { StoreRepository } from '../repositories/StoreRepository'
import { OrderSamplingService } from '../services'

const ABSENT_STORE_ID = testId()

class HasOrdersStub extends OrderSamplingService {
	constructor(private readonly v: boolean) {
		super()
	}
	async hasOrdersForStore(_storeId: string): Promise<boolean> {
		return this.v
	}
}

describe('GetStorePreferencesSettings query use case (T09)', () => {
	let testBed: TestBed
	let testContainer: DependencyContainer
	let get: GetStorePreferencesSettings
	let update: UpdateStorePreferences
	let storeRepo: StoreRepository

	beforeAll(async () => {
		testContainer = container.createChildContainer()
		testContainer.register(OrderSamplingService as never, { useValue: new HasOrdersStub(false) })
		testBed = await TestBed.create('integration', { testContainer, ownerId: 'integration-tenant' })
		get = testBed.resolve(GetStorePreferencesSettings)
		update = testBed.resolve(UpdateStorePreferences)
		storeRepo = testBed.resolve(StoreRepository)
	})
	beforeEach(async () => {
		await testBed.reset()
	})
	afterAll(async () => {
		await testBed.destroy()
	})

	it('returns the prefs DTO from a freshly created store', async () => {
		const s = Store.create({
			name: 'Acme',
			reportingCurrency: CurrencyCode.USD,
			timezone: 'America/Sao_Paulo',
		})
		await storeRepo.save(s)

		const out = await get.execute({ storeId: s.id.value })
		expect(out).toMatchObject({
			storeId: s.id.value,
			reportingCurrency: CurrencyCode.USD,
			timezone: 'America/Sao_Paulo',
			showStoreNameInNotifications: true,
		})
		expect(typeof out.updatedAt).toBe('string')
	})

	it('reflects an update after UpdateStorePreferences runs', async () => {
		const s = Store.create({
			name: 'Acme',
			reportingCurrency: CurrencyCode.USD,
			timezone: 'UTC',
		})
		await storeRepo.save(s)

		await update.execute({
			storeId: s.id.value,
			updatedByUserId: testId('user', '1'),
			reportingCurrency: CurrencyCode.BRL,
			showStoreNameInNotifications: false,
		})

		const out = await get.execute({ storeId: s.id.value })
		expect(out.reportingCurrency).toBe(CurrencyCode.BRL)
		expect(out.showStoreNameInNotifications).toBe(false)
		expect(out.timezone).toBe('UTC')
	})

	it('throws STORE_NOT_FOUND for an absent storeId', async () => {
		await expect(get.execute({ storeId: ABSENT_STORE_ID })).rejects.toMatchObject({ name: 'STORE_NOT_FOUND' })
	})
})

