import { beforeEach, describe, expect, it } from 'bun:test'
import { PaymentStatus, CurrencyCode } from '@bk-dash/contracts-typescript/wire/enums'
import { testId } from '@test/support'
import { OrderOverride } from '../../entities/OrderOverride'
import { MockOrderOverrideRepository } from './MockOrderOverrideRepository'
import type { OrderOverrideFieldsInput } from '../../objects/OrderOverrideFields'

const STORE = testId('store', '1')
const USER = 'user-1'

function makeOverride(opts: { orderId: string; externalId: string; fields?: OrderOverrideFieldsInput }): OrderOverride {
	return OrderOverride.create({
		storeId: STORE,
		orderId: opts.orderId,
		storeIntegrationExternalId: opts.externalId,
		fields: opts.fields ?? defaultFields(),
	})
}

function defaultFields(): OrderOverrideFieldsInput {
	return {
		paymentStatus: PaymentStatus.PAID,
		revenue: { amountCents: 5000, currency: CurrencyCode.USD },
	}
}

describe('MockOrderOverrideRepository', () => {
	let repo: MockOrderOverrideRepository

	beforeEach(() => {
		repo = new MockOrderOverrideRepository()
	})

	it('findByPin returns the seeded override', async () => {
		const o = makeOverride({ orderId: 'order-1', externalId: 'shop.myshopify.com' })
		repo.seed(o)
		const found = await repo.findByPin('order-1', 'shop.myshopify.com')
		expect(found?.orderId.value).toBe('order-1')
	})

	it('findByPin discriminates by storeIntegrationExternalId (same orderId, different shops)', async () => {
		repo.seed(makeOverride({ orderId: 'order-2', externalId: 'shop-a.myshopify.com' }))
		repo.seed(makeOverride({ orderId: 'order-2', externalId: 'shop-b.myshopify.com' }))

		const a = await repo.findByPin('order-2', 'shop-a.myshopify.com')
		const b = await repo.findByPin('order-2', 'shop-b.myshopify.com')
		const miss = await repo.findByPin('order-2', 'shop-c.myshopify.com')

		expect(a?.storeIntegrationExternalId).toBe('shop-a.myshopify.com')
		expect(b?.storeIntegrationExternalId).toBe('shop-b.myshopify.com')
		expect(miss).toBeUndefined()
	})

	it('save increments version and persists by (orderId, externalId)', async () => {
		const o = makeOverride({ orderId: 'order-3', externalId: 'shop.myshopify.com' })
		const initialVersion = o.version
		await repo.save(o)
		expect(o.version).toBe(initialVersion + 1)
		const found = await repo.findByPin('order-3', 'shop.myshopify.com')
		expect(found?.version).toBe(initialVersion + 1)
	})

	it('delete by orderId removes every shop variant', async () => {
		repo.seed(makeOverride({ orderId: 'order-4', externalId: 'shop-a.myshopify.com' }))
		repo.seed(makeOverride({ orderId: 'order-4', externalId: 'shop-b.myshopify.com' }))
		repo.seed(makeOverride({ orderId: 'order-5', externalId: 'shop-a.myshopify.com' }))

		await repo.delete('order-4')

		expect(await repo.findByPin('order-4', 'shop-a.myshopify.com')).toBeUndefined()
		expect(await repo.findByPin('order-4', 'shop-b.myshopify.com')).toBeUndefined()
		expect(await repo.findByPin('order-5', 'shop-a.myshopify.com')).toBeDefined()
	})

	it('clear empties the store', async () => {
		repo.seed(makeOverride({ orderId: 'order-6', externalId: 'shop.myshopify.com' }))
		repo.clear()
		expect(await repo.findByPin('order-6', 'shop.myshopify.com')).toBeUndefined()
	})
})

import { afterAll, beforeAll, beforeEach, describe, expect, it } from 'bun:test'
import { container, type DependencyContainer } from 'tsyringe-neo'
import { TestBed, testId } from '@test/support'
import { DomainEventRepository } from '@bk-dash/core-typescript'
import { CurrencyCode } from '@bk-dash/contracts-typescript/wire/enums'
import { RecordManualAdSpend } from './RecordManualAdSpend'
import { UpdateManualAdSpend } from './UpdateManualAdSpend'
import { DeleteManualAdSpend } from './DeleteManualAdSpend'
import { AdSpendManualRepository } from '../repositories/AdSpendManualRepository'
import { ManualAdSpendDeletedEvent, ManualAdSpendRecordedEvent, ManualAdSpendUpdatedEvent } from '../events'

const STORE = testId('store', '1')
const USER = testId('user', '1')

describe('Manual AdSpend (C33 + C34 + C35)', () => {
	let testBed: TestBed
	let testContainer: DependencyContainer
	let record: RecordManualAdSpend
	let update: UpdateManualAdSpend
	let del: DeleteManualAdSpend
	let repo: AdSpendManualRepository

	beforeAll(async () => {
		testContainer = container.createChildContainer()
		testBed = await TestBed.create('integration', { testContainer, ownerId: 'integration-tenant' })
		record = testBed.resolve(RecordManualAdSpend)
		update = testBed.resolve(UpdateManualAdSpend)
		del = testBed.resolve(DeleteManualAdSpend)
		repo = testBed.resolve(AdSpendManualRepository)
	})
	beforeEach(async () => {
		await testBed.reset()
	})
	afterAll(async () => {
		await testBed.destroy()
	})

	async function readRecordedEvents() {
		return testBed.resolve(DomainEventRepository).findByType(ManualAdSpendRecordedEvent)
	}
	async function readUpdatedEvents() {
		return testBed.resolve(DomainEventRepository).findByType(ManualAdSpendUpdatedEvent)
	}
	async function readDeletedEvents() {
		return testBed.resolve(DomainEventRepository).findByType(ManualAdSpendDeletedEvent)
	}

	describe('RecordManualAdSpend (C33)', () => {
		it('persists a MANUAL AdSpendManual + emits ManualAdSpendRecordedEvent', async () => {
			const out = await record.execute({
				userId: USER,
				storeId: STORE,
				startDate: new Date('2026-05-01T00:00:00.000Z'),
				endDate: new Date('2026-05-31T00:00:00.000Z'),
				currency: CurrencyCode.USD,
				amountCents: 10_000,
				description: 'May spend',
			})

			expect(out.adSpendId).toMatch(/^[0-9a-f-]{36}$/)
			const saved = await repo.findById(out.adSpendId)
			expect(saved?.platform).toBeUndefined()
			expect(saved?.spend.amountCents).toBe(10_000)
			expect(saved?.createdByUserId.value).toBe(USER)

			const emitted = await readRecordedEvents()
			expect(emitted).toHaveLength(1)
			expect(emitted[0]!.payload.adSpend).toBeDefined()
			expect(emitted[0]!.payload.adSpend.spend.amountCents).toBe(10_000)
		})

		it('propagates INVALID_DATE_RANGE when startDate > endDate', async () => {
			await expect(
				record.execute({
					userId: USER,
					storeId: STORE,
					startDate: new Date('2026-06-30T00:00:00.000Z'),
					endDate: new Date('2026-06-01T00:00:00.000Z'),
					currency: CurrencyCode.USD,
					amountCents: 100,
				}),
			).rejects.toMatchObject({ name: 'INVALID_DATE_RANGE' })
		})
	})

	describe('UpdateManualAdSpend (C34)', () => {
		async function seedManual(): Promise<string> {
			const { adSpendId } = await record.execute({
				userId: USER,
				storeId: STORE,
				startDate: new Date('2026-05-01T00:00:00.000Z'),
				endDate: new Date('2026-05-31T00:00:00.000Z'),
				currency: CurrencyCode.USD,
				amountCents: 5_000,
			})
			return adSpendId
		}

		it('updates name + description + emits with changedFields', async () => {
			const adSpendId = await seedManual()

			await update.execute({ userId: USER, adSpendId, name: 'new', description: 'updated' })

			const saved = await repo.findById(adSpendId)
			expect(saved?.name).toBe('new')
			expect(saved?.description).toBe('updated')

			const emitted = await readUpdatedEvents()
			expect(emitted).toHaveLength(1)
			expect(emitted[0]!.payload.adSpend).toBeDefined()
			expect(emitted[0]!.payload.adSpend.name).toBe('new')
		})

		it('updates spend (amountCents only — uses existing currency)', async () => {
			const adSpendId = await seedManual()

			await update.execute({ userId: USER, adSpendId, amountCents: 9_999 })

			const saved = await repo.findById(adSpendId)
			expect(saved?.spend.amountCents).toBe(9_999)
			expect(saved?.spend.currency).toBe(CurrencyCode.USD) // preserved
		})

		it('emits ManualAdSpendUpdatedEvent even when no fields supplied (always-publish)', async () => {
			const adSpendId = await seedManual()
			await update.execute({ userId: USER, adSpendId })
			const updated = await readUpdatedEvents()
			expect(updated).toHaveLength(1)
			expect(updated[0]!.payload.adSpend).toBeDefined()
		})

		it('throws AD_SPEND_NOT_FOUND on missing id', async () => {
			await expect(update.execute({ userId: USER, adSpendId: testId(), name: 'x' })).rejects.toMatchObject({ name: 'AD_SPEND_NOT_FOUND' })
		})
	})

	describe('DeleteManualAdSpend (C35)', () => {
		it('hard-deletes the MANUAL AdSpendManual + emits ManualAdSpendDeletedEvent', async () => {
			const { adSpendId } = await record.execute({
				userId: USER,
				storeId: STORE,
				startDate: new Date('2026-05-01T00:00:00.000Z'),
				endDate: new Date('2026-05-31T00:00:00.000Z'),
				currency: CurrencyCode.USD,
				amountCents: 5_000,
			})

			await del.execute({ userId: USER, adSpendId })

			expect(await repo.findById(adSpendId)).toBeUndefined()
			const emitted = await readDeletedEvents()
			expect(emitted).toHaveLength(1)
			expect(emitted[0]!.payload.adSpendId).toBe(adSpendId)
		})

		it('throws AD_SPEND_NOT_FOUND on missing id', async () => {
			await expect(del.execute({ userId: USER, adSpendId: testId() })).rejects.toMatchObject({ name: 'AD_SPEND_NOT_FOUND' })
		})
	})
})

import { afterAll, beforeAll, beforeEach, describe, expect, it } from 'bun:test'
import { container, type DependencyContainer } from 'tsyringe-neo'
import { TestBed, testId } from '@test/support'
import { DomainEventRepository } from '@bk-dash/core-typescript'
import { CurrencyCode, PaymentStatus } from '@bk-dash/contracts-typescript/wire/enums'
import { MonetaryAmount } from '../../shared/objects'
import { UpdateOrderOverride } from './UpdateOrderOverride'
import { OrderOverrideRepository } from '../repositories/OrderOverrideRepository/OrderOverrideRepository'
import { OrderOverriddenEvent } from '../events'

const STORE = testId('store', '1')
const ORDER_A = testId('order', 'a')
const ORDER_B = testId('order', 'b')
const EXT_A = 'shop-a.myshopify.com'
const EXT_B = 'shop-b.myshopify.com'
const USER_1 = testId('user', '1')
const USER_2 = testId('user', '2')

describe('UpdateOrderOverride (C26)', () => {
	let testBed: TestBed
	let testContainer: DependencyContainer
	let useCase: UpdateOrderOverride
	let repo: OrderOverrideRepository

	beforeAll(async () => {
		testContainer = container.createChildContainer()
		testBed = await TestBed.create('integration', { testContainer, ownerId: 'integration-tenant' })
		useCase = testBed.resolve(UpdateOrderOverride)
		repo = testBed.resolve(OrderOverrideRepository)
	})
	beforeEach(async () => {
		await testBed.reset()
	})
	afterAll(async () => {
		await testBed.destroy()
	})

	async function readOverriddenEvents() {
		return testBed.resolve(DomainEventRepository).findByType(OrderOverriddenEvent)
	}

	it('creates a fresh override on first call + emits with all fields as changed', async () => {
		const out = await useCase.execute({
			userId: USER_1,
			storeId: STORE,
			orderId: ORDER_A,
			storeIntegrationExternalId: EXT_A,
			patch: {
				paymentStatus: PaymentStatus.PAID,
				revenue: new MonetaryAmount({ amountCents: 10_000, currency: CurrencyCode.USD }),
			},
		})

		expect(out.orderOverrideId).toMatch(/^[0-9a-f-]{36}$/)

		const saved = await repo.findByPin(ORDER_A, EXT_A)
		expect(saved?.fields.paymentStatus).toBe(PaymentStatus.PAID)
		expect(saved?.fields.revenue).toEqual(new MonetaryAmount({ amountCents: 10_000, currency: CurrencyCode.USD }))
		// Note: the order_overrides table doesn't carry an updatedByUserId
		// column — the audit lives in the OrderOverriddenEvent payload below.

		const emitted = await readOverriddenEvents()
		expect(emitted).toHaveLength(1)
		expect(emitted[0]!.payload.orderId).toBe(ORDER_A)
		expect(emitted[0]!.payload.storeIntegrationExternalId).toBe(EXT_A)
		expect(emitted[0]!.payload.entity.fields.paymentStatus).toBe(PaymentStatus.PAID)
		expect(emitted[0]!.payload.entity.fields.revenue).toEqual({ amountCents: 10_000, currency: CurrencyCode.USD })
		expect(emitted[0]!.payload.updatedByUserId).toBe(USER_1)
	})

	it('merges patch into existing override + emits only the changed keys', async () => {
		// first call: set paymentStatus + revenue
		await useCase.execute({
			userId: USER_1,
			storeId: STORE,
			orderId: ORDER_A,
			storeIntegrationExternalId: EXT_A,
			patch: {
				paymentStatus: PaymentStatus.PAID,
				revenue: new MonetaryAmount({ amountCents: 10_000, currency: CurrencyCode.USD }),
			},
		})

		// second call by a different user: change paymentStatus + add fees (revenue unchanged)
		await useCase.execute({
			userId: USER_2,
			storeId: STORE,
			orderId: ORDER_A,
			storeIntegrationExternalId: EXT_A,
			patch: {
				paymentStatus: PaymentStatus.REFUNDED,
				fees: new MonetaryAmount({ amountCents: 250, currency: CurrencyCode.USD }),
			},
		})

		const saved = await repo.findByPin(ORDER_A, EXT_A)
		// revenue preserved, paymentStatus updated, fees added
		expect(saved?.fields.revenue).toEqual(new MonetaryAmount({ amountCents: 10_000, currency: CurrencyCode.USD }))
		expect(saved?.fields.paymentStatus).toBe(PaymentStatus.REFUNDED)
		expect(saved?.fields.fees).toEqual(new MonetaryAmount({ amountCents: 250, currency: CurrencyCode.USD }))

		const emitted = await readOverriddenEvents()
		expect(emitted).toHaveLength(2)
		expect(emitted[1]!.payload.entity.fields.paymentStatus).toBe(PaymentStatus.REFUNDED)
		expect(emitted[1]!.payload.entity.fields.fees).toEqual({ amountCents: 250, currency: CurrencyCode.USD })
	})

	it('is a no-op + emits no event when the patch matches existing fields', async () => {
		await useCase.execute({
			userId: USER_1,
			storeId: STORE,
			orderId: ORDER_A,
			storeIntegrationExternalId: EXT_A,
			patch: { paymentStatus: PaymentStatus.PAID },
		})

		const beforeId = (await repo.findByPin(ORDER_A, EXT_A))!.id.value

		const out = await useCase.execute({
			userId: USER_2,
			storeId: STORE,
			orderId: ORDER_A,
			storeIntegrationExternalId: EXT_A,
			patch: { paymentStatus: PaymentStatus.PAID }, // same value
		})

		expect(out.orderOverrideId).toBe(beforeId)
		const saved = await repo.findByPin(ORDER_A, EXT_A)
		// fields unchanged — paymentStatus still PAID from the first call.
		expect(saved?.fields.paymentStatus).toBe(PaymentStatus.PAID)

		const emitted = await readOverriddenEvents()
		expect(emitted).toHaveLength(1) // only the first create's event
	})

	it('discriminates by (orderId, storeIntegrationExternalId) — independent overrides per shop', async () => {
		await useCase.execute({
			userId: USER_1,
			storeId: STORE,
			orderId: ORDER_A,
			storeIntegrationExternalId: EXT_A,
			patch: { paymentStatus: PaymentStatus.PAID },
		})
		await useCase.execute({
			userId: USER_1,
			storeId: STORE,
			orderId: ORDER_A,
			storeIntegrationExternalId: EXT_B,
			patch: { paymentStatus: PaymentStatus.REFUNDED },
		})
		await useCase.execute({
			userId: USER_1,
			storeId: STORE,
			orderId: ORDER_B,
			storeIntegrationExternalId: EXT_A,
			patch: { paymentStatus: PaymentStatus.PENDING },
		})

		const oa = await repo.findByPin(ORDER_A, EXT_A)
		const ob = await repo.findByPin(ORDER_A, EXT_B)
		const oc = await repo.findByPin(ORDER_B, EXT_A)
		expect(oa?.fields.paymentStatus).toBe(PaymentStatus.PAID)
		expect(ob?.fields.paymentStatus).toBe(PaymentStatus.REFUNDED)
		expect(oc?.fields.paymentStatus).toBe(PaymentStatus.PENDING)
		expect(oa?.id.value).not.toBe(ob?.id.value)

		const emitted = await readOverriddenEvents()
		expect(emitted).toHaveLength(3)
	})
})

